/* Rest and its count to the deep rest decide when the board rests
 * (gui_deep_tick()). AO_LowPower's own idle count would cut Rest short and
 * put the glass out, so kodeOS builds without it. */
#ifdef CONFIG_KODE_LOWPOWER_IDLE
#error "kgui's Rest decides the idle time: CONFIG_KODE_LOWPOWER_IDLE must be off"
#endif

/* AO_Gui's private signals, numbered from MAX_SIG exactly as an app's own
 * are (see the SDK's examples): posted to self, never published, so they need
 * no slot in the shared catalog. */
enum {
    GUI_TICK_SIG = MAX_SIG,     /**< The render-pass QTimeEvt. */
    GUI_KEEP_RETRY_SIG,         /**< The card's copy was refused: ask again (gui_keep_read_next()). */
    GUI_SETTINGS_TOGGLE_SIG,    /**< The settings door. The face and Apps open
                                 *   the settings screen over themselves on it,
                                 *   as a curtain,
                                 *   and the settings screen goes back to
                                 *   what it came down over; a card on a
                                 *   settings page, a system card and the
                                 *   guided tests swallow it - the settings
                                 *   screen is under the first already.
                                 *   Posted by the top button held and the
                                 *   bottom button's release, on Apps, where
                                 *   it opens the settings screen, and on the
                                 *   settings screen, where it goes back. A
                                 *   drag down from the top band, or up on the
                                 *   settings screen, is the recognizer's and
                                 *   starts the curtain itself
                                 *   (gui_drag_claim()); with no pictures
                                 *   that curtain lands at once with a cut,
                                 *   through GUI_CURTAIN_LAND_SIG
                                 *   (gui_curtain_cut()). */
    GUI_SHEET_OPEN_SIG,         /**< A sheet was asked for: by a control, a
                                 *   launcher row, a write, a pairing, or a
                                 *   row that opens a list in its own page's
                                 *   place (About's Time zone, Screen's
                                 *   Auto-lock). Carries the kind in a
                                 *   SheetOpenEvt rather than being written
                                 *   into the AO by the caller: which sheet
                                 *   is up is state, and state changes where
                                 *   the state machine says so. A sheet
                                 *   already up answers it in place
                                 *   (gui_sheet_body()): it takes the kind
                                 *   over without a slide, or refuses one
                                 *   that may not open there
                                 *   (gui_sheet_open_taken()). */
    GUI_SHEET_CLOSE_SIG,        /**< Take the sheet away. NO SHEET CLOSES BY
                                 *   ITSELF (the owner's rule, 2026-09-15):
                                 *   the bottom button's release, a drag
                                 *   down on a card's header (gui_card_land()
                                 *   takes the same door), an
                                 *   answer on the card, a held bottom
                                 *   button (HOME_SIG) and the pairing's own
                                 *   outcome are
                                 *   the whole list, plus the locked Opening
                                 *   card, which nothing can press and so
                                 *   leaves when its write is done - all but
                                 *   the launcher's own, which stays for the
                                 *   edge's close and the restart into the
                                 *   app. A tap on the blocker is not on that
                                 *   list. On a list of choices the same
                                 *   signal goes back to the page the list
                                 *   opened from (About, or Screen), and the
                                 *   card stays up.                         */
    GUI_SHEET_REFILL_SIG,       /**< A row changed something the whole sheet
                                 *   is a view of. Posted and never done on
                                 *   the spot: the rebuild deletes every row,
                                 *   and the caller may be the LVGL click
                                 *   callback of one of them - LVGL forbids
                                 *   deleting an object from inside its own
                                 *   event. Coming back through the queue is
                                 *   also what lets the answer be felt at the
                                 *   new setting before the glass catches
                                 *   up. */
    GUI_FACE_SIG,               /**< The door down to the face: the auto-lock
                                 *   that the launcher and the settings screen
                                 *   post from their tick once the chosen
                                 *   time has gone by without input
                                 *   (gui_idle_check()) - from the tick,
                                 *   which a child must hand up to
                                 *   Gui_running rather than transition out
                                 *   of, so the transition happens one
                                 *   dispatch later, off this signal. Apps
                                 *   brings the face down over itself as a
                                 *   curtain, and the settings screen has
                                 *   the face come down over it the same
                                 *   way; the face is already there; a
                                 *   sheet and the guided tests swallow it,
                                 *   because no sheet closes by itself. */
    GUI_LAUNCHER_SIG,           /**< The unlock: the door up to the
                                 *   launcher, from the face - the top
                                 *   button; a finger up on the face takes
                                 *   the curtain itself. Posted and answered
                                 *   the same way; only the face takes it,
                                 *   as a curtain that takes the face up. */
    GUI_ASSETS_SIG,             /**< One of the `assets_*` console functions:
                                 *   a GuiAssetsCmdEvt, posted from AO_Console's
                                 *   task, where the function's run executes,
                                 *   and answered on every screen
                                 *   (gui_assets_cmd()). */
    GUI_CURTAIN_LAND_SIG,       /**< The curtain has landed on the
                                 *   far side: posted from the tick, which
                                 *   must not transition, and answered by
                                 *   the screen the curtain moves over with
                                 *   the door it was started for
                                 *   (gui_curtain_settle()). One that
                                 *   arrives after the landing was taken by
                                 *   an event that finished the curtain
                                 *   first finds no curtain and does
                                 *   nothing. */
    GUI_CARD_LAND_SIG,          /**< A card that a finger took by its header
                                 *   has landed, up where it rests or down
                                 *   off the glass: posted from the tick for
                                 *   the curtain's reason and answered by the
                                 *   card's own state (gui_card_settle()),
                                 *   which leaves as the bottom button does
                                 *   when the card landed down. One that
                                 *   arrives after the landing was taken by
                                 *   an event that finished the drag first
                                 *   finds no drag and does nothing. */
    GUI_REST_SIG,               /**< The door from the awake Lock to Rest:
                                 *   the bottom button released, and the time
                                 *   without input (gui_rest_check()), which
                                 *   post it from where nothing may
                                 *   transition. The awake Lock answers it
                                 *   when nothing is going on
                                 *   (gui_rest_ok()); a card up and Rest
                                 *   itself swallow it. */
    GUI_RETURN_SIG              /**< The first frame after an app may go:
                                 *   the installed list ended or the wait
                                 *   for it ran out. Posted from the list's
                                 *   end and from the tick, which must not
                                 *   transition, and answered by the state
                                 *   that holds the frame back
                                 *   (Gui_returning). */
};

/**
 * @brief Which sheet is on the glass.
 *
 * One per settings page that has something to say, and NONE for the ordinary
 * case; then the two lists of choices, each a page a sheet opens from a row
 * of its own - About's zones and Screen's auto-lock times; then the kinds
 * that belong to no page at all - a row of the launcher, a write in flight,
 * a write that failed, the ending, a peer asking to pair, an app that
 * stopped, a battery that is critical. The first seven
 * LIST and the rest SPEAK, which is the whole difference between them: a
 * listing sheet's body is rows, a speaking sheet's is lines of text and up
 * to one button, and `me->sheet_n` tells the pad which grammar it is under.
 * The keypad is the last of them and neither: its content is one module's
 * (kgui_keyboard.h), it opens in place over the Wi-Fi page like a list does,
 * and the pad's grammar on it is the keypad's (gui_kbd_pad()).
 */
typedef enum {
    GUI_SHEET_NONE = 0,
    GUI_SHEET_WIFI,
    GUI_SHEET_BLE,
    GUI_SHEET_SCREEN,
    GUI_SHEET_BAT,
    GUI_SHEET_ABOUT,
    GUI_SHEET_MORE,
    GUI_SHEET_ZONE,
    GUI_SHEET_TIME,
    GUI_SHEET_AUTOLOCK,
    GUI_SHEET_DETAILS,
    GUI_SHEET_OPENING,
    GUI_SHEET_FAILURE,
    GUI_SHEET_POWEROFF,   /* "Turn off?" */
    GUI_SHEET_PAIRING,
    GUI_SHEET_TEST,
    GUI_SHEET_KODY,
    GUI_SHEET_KEYPAD,
    GUI_SHEET_STOPPED,
    GUI_SHEET_BATTERY,
    GUI_SHEET_REMOVE,
    GUI_SHEET_REMOVING,
    GUI_SHEET_RESET,      /* "Factory reset?" */
    GUI_SHEET_RESETTING   /* the wait for AO_Boot, then why it did not happen */
} GuiSheet;

/**
 * @brief What a sheet is called in the log.
 *
 * One row per kind, in the enum's own order. A kind added without a name
 * fails the build at the length check, rather than shifting every later name
 * by one in the log. Only the log reads this - the glass says what a card is
 * about in its own header, in the reader's words rather than these.
 *
 * @param kind Which sheet.
 * @return Its name; "?" for anything outside the enum.
 */
static const char *gui_sheet_kind_name(GuiSheet kind)
{
    static const char *const NAMES[] = {
        "none", "wifi", "ble", "screen", "bat", "about", "more", "zone", "time",
        "autolock", "details", "opening", "failure", "poweroff", "pairing",
        "selftest", "kody", "keypad", "stopped", "battery", "remove", "removing",
        "reset", "resetting"
    };
    _Static_assert((sizeof(NAMES) / sizeof(NAMES[0])) == ((size_t)GUI_SHEET_RESETTING + 1U),
                   "one name per GuiSheet, in the enum's order");
    const char *name = "?";

    if ( (size_t)kind < (sizeof(NAMES) / sizeof(NAMES[0])) )
    {
        name = NAMES[kind];
    }
    return name;
}

/**
 * @brief One kind of system card.
 *
 * ONE RULE FOR EVERY SYSTEM CARD, and this table is where its kinds are
 * listed: the card covers the whole glass; it rises from the bottom edge
 * (kgui_rise.h); it ignores every input for KGUI_RISE_INPUT_MS from its
 * arrival; nothing in its body closes it, no drag and no tap but the one on
 * its button; and BOT closes it wherever it can be closed - the locked
 * Opening card of a running write cannot be.
 * What differs between the kinds is only what is in a row of this table.
 */
typedef struct {
    GuiSheet kind;       /**< Which sheet.                                     */
    bool     over_face;  /**< It may rise over the lock screen: it opens no
                           *   page behind it.                                  */
} GuiSysCard;

/**
 * @brief The row of a sheet kind in the table of system cards.
 *
 * THE TABLE: a write in flight, the failure of one, a pairing, an app that
 * stopped, a battery that is critical, the ending, and the factory reset's
 * question and its wait. Every question about which cards are system cards
 * is asked of it, through this function.
 *
 * @param kind Which sheet.
 * @return Its row; NULL for a kind that is no system card.
 */
static const GuiSysCard *gui_syscard_of(GuiSheet kind)
{
    static const GuiSysCard TABLE[] = {
        { GUI_SHEET_OPENING,   true  },
        { GUI_SHEET_FAILURE,   true  },
        { GUI_SHEET_PAIRING,   true  },
        { GUI_SHEET_STOPPED,   true  },
        { GUI_SHEET_BATTERY,   true  },
        { GUI_SHEET_POWEROFF,  true  },
        { GUI_SHEET_RESET,     false },
        { GUI_SHEET_RESETTING, false },
    };
    const GuiSysCard *found = NULL;

    for ( size_t i = 0U;
         (i < (sizeof(TABLE) / sizeof(TABLE[0]))) && (NULL == found);
         ++i )
    {
        if ( TABLE[i].kind == kind )
        {
            found = &TABLE[i];
        }
    }
    return found;
}

/**
 * @brief Whether a sheet is one of the system's own cards.
 *
 * The kinds of the table (gui_syscard_of()) rise from the bottom edge, refuse
 * input while they arrive, and are closed by the bottom button or an answer on
 * them. Every other sheet is closed by a drag down on its header as well as
 * by the bottom button.
 *
 * @param kind Which sheet.
 * @return true for a system card.
 */
static bool gui_sheet_is_system(GuiSheet kind)
{
    return gui_syscard_of(kind) != NULL;
}

/**
 * @brief Whether a sheet is a settings page: a kshell page of the rail.
 *
 * Wi-Fi, Bluetooth, More and the pages More opens, and the two lists of
 * choices under them, wear kshell's dress: no header disc, the page's name
 * centred over the glass, and rows that are discs on the page rather than
 * capsules, the focused one always at the same height. They go back one level
 * with BOT or a swipe right. The keypad is its own layout, and every other
 * kind is a card.
 *
 * @param kind Which sheet.
 * @return true for a settings page.
 */
static bool gui_sheet_is_page(GuiSheet kind)
{
    bool page = false;

    switch ( kind )
    {
        case GUI_SHEET_WIFI:
        case GUI_SHEET_BLE:
        case GUI_SHEET_SCREEN:
        case GUI_SHEET_BAT:
        case GUI_SHEET_ABOUT:
        case GUI_SHEET_MORE:
        case GUI_SHEET_ZONE:
        case GUI_SHEET_TIME:
        case GUI_SHEET_AUTOLOCK:
        case GUI_SHEET_TEST:
        case GUI_SHEET_KODY: {
            page = true;
            break;
        }
        default: {
            break;
        }
    }
    return page;
}

/**
 * @brief Whether a settings page pins its first row to the top.
 *
 * Wi-Fi and Bluetooth: the switch stays at the top of the page, under no
 * title, and the rest is a plain list that scrolls under it - the least
 * scroll that shows the ringed row, not the rail's fixed height
 * (gui_sheet_pin_first()).
 *
 * @param kind Which sheet.
 * @return true for the two radio pages.
 */
static bool gui_sheet_pins(GuiSheet kind)
{
    return (GUI_SHEET_WIFI == kind) || (GUI_SHEET_BLE == kind);
}

/**
 * @brief Whether a sheet is one of the three cards the details module draws.
 *
 * The details of an app, the question before Remove and the wait while the
 * app leaves share one set of pages (kgui_details.h), kept while the card
 * turns from one into another.
 *
 * @param kind Which sheet.
 * @return true for the details, Remove and Removing.
 */
static bool gui_sheet_is_details(GuiSheet kind)
{
    return (GUI_SHEET_DETAILS == kind) || (GUI_SHEET_REMOVE == kind)
           || (GUI_SHEET_REMOVING == kind);
}

/**
 * @brief Whether a sheet may rise over the lock screen.
 *
 * @param kind Which sheet.
 * @return true for the system cards that open no page behind them.
 */
static bool gui_sheet_over_face(GuiSheet kind)
{
    GuiSysCard const * const card = gui_syscard_of(kind);

    return (NULL != card) && card->over_face;
}

/**
 * @brief A door, as an input asks for it.
 *
 * Recorded where the input is seen and posted by gui_door_post() as the
 * door's own signal; what it means is decided by the state that answers.
 */
typedef enum {
    GUI_DOOR_NONE = 0,      /**< Nothing asked for.                          */
    GUI_DOOR_SETTINGS,      /**< GUI_SETTINGS_TOGGLE_SIG: into the settings
                              *   screen, or back out of it.                 */
    GUI_DOOR_FACE,          /**< GUI_FACE_SIG: the auto-lock.                */
    GUI_DOOR_LAUNCHER,      /**< GUI_LAUNCHER_SIG: the unlock.               */
    GUI_DOOR_HOME,          /**< GUI_FACE_SIG, in the event of its own
                              *   (s_home_evt): back from Apps to the face,
                              *   which slides in from the left instead of
                              *   coming down.                               */
    GUI_DOOR_REST,          /**< GUI_REST_SIG: the awake Lock to Rest.       */
    GUI_DOOR_COUNT          /**< How many there are, NONE included: what
                              *   door_why is indexed by.                    */
} GuiDoor;

/**
 * @brief What a drag of the finger is for, in the words the log speaks.
 *
 * One kind per thing a drag opens or moves. The recognizer names what a
 * claimed drag is where the press landed (gui_gesture_zone()), and the log
 * speaks the name.
 */
typedef enum {
    GUI_KIND_NONE = 0,      /**< Nothing: no drag was claimed.              */
    GUI_KIND_UNLOCK,        /**< The face up off the launcher.               */
    GUI_KIND_DISMISS,       /**< The Turn off card down and away: a no.      */
    GUI_KIND_SETTINGS,      /**< The launcher down into the settings screen. */
    GUI_KIND_LEVEL,         /**< The launcher into a group or an app, or back. */
    GUI_KIND_SCROLL,        /**< The launcher's list moving with the finger. */
    GUI_KIND_CLOSE,         /**< The settings screen up and away.            */
    GUI_KIND_SHEET,         /**< A card down and away.                       */
    GUI_KIND_BACK,          /**< A settings page right and away: one level back. */
    GUI_KIND_LOCK,          /**< The face down over the launcher, pulled by
                              *   the list.                                  */
    GUI_KIND_APPS,          /**< The face sideways into Apps.                */
    GUI_KIND_COUNT          /**< How many there are, NONE included: what
                              *   the names are indexed by.                  */
} GuiKind;

/**
 * @brief What a press may become where it landed: its zone.
 *
 * Chosen once, on the press edge, by gui_gesture_zone(): the recognizer is
 * told `allowed` and `blocked`, and the kind of a claim is read back from
 * `vert` or `horz` by the claimed direction.
 */
typedef struct {
    uint8_t allowed;        /**< The KUI_GESTURE_DIR_* bits the zone takes; 0
                              *   where no drag is born.                     */
    bool    blocked;        /**< Input is shut: the press never claims.      */
    bool    catches;        /**< The press lands on a settling curtain and
                              *   catches it in flight.                      */
    bool    header;         /**< The press lands in the header of a card:
                              *   a claimed drag down takes the card with
                              *   the finger (gui_card_begin()).             */
    bool    list_catch;     /**< The press lands on the Apps list while it
                              *   moves and catches it where it is
                              *   (gui_list_touch()).                        */
    GuiKind vert;           /**< What a claim up or down is for here.        */
    GuiKind down;           /**< What a claim down is for when it is not what
                              *   a claim up is for; NONE: vert.             */
    GuiKind horz;           /**< What a claim left or right is for here.     */
} GuiTouchZone;

/**
 * @brief Which curtain: what the panel is and what it does to the screen
 *        under it.
 *
 * All are one curtain - a screen of two still pictures, a page that a
 * finger or a spring moves, a landing that changes the state - and differ in
 * the table below (s_curtain_looks) and in the screens they join.
 */
typedef enum {
    GUI_CURTAIN_SETTINGS = 0,   /**< The settings screen comes down over the
                                  *   face, Apps or a card, dimming it.      */
    GUI_CURTAIN_FACE,           /**< The face comes down over Apps (the lock)
                                  *   and goes back up (the unlock), no dim. */
    GUI_CURTAIN_FACE_OVER_SETTINGS,
                                /**< The face comes down over the settings
                                  *   screen (the lock from Settings), no
                                  *   dim. It only comes down: there is no
                                  *   unlock to go back to Settings.         */
    GUI_CURTAIN_FACE_SLIDE,     /**< The face and Apps slide along the glass
                                  *   in GUI_PAGE_ANIM_MS, easing out (spec
                                  *   section 9): the face leaves to the left
                                  *   as Apps comes in from the right, and
                                  *   the way back (opens). Not a spring and
                                  *   not a finger's: a door's.              */
    GUI_CURTAIN_FACE_GROW,      /**< Apps fades in where the face was, in
                                  *   place, in GUI_PAGE_ANIM_MS: the door a
                                  *   tap or TOP takes (the apocrifa's), with
                                  *   no inverse - the way back slides. On
                                  *   the clock, as the slide.               */
    GUI_CURTAIN_KINDS           /**< How many there are.                     */
} GuiCurtainKind;

/**
 * @brief Where the settings screen was opened from, and so where it goes back.
 */
typedef enum {
    GUI_FROM_APPS = 0,      /**< Closing returns to Apps (HOME out of Settings). */
    GUI_FROM_FACE           /**< Over the Lock: closing returns to the face. */
} GuiFrom;

/**
 * @brief What holds the Apps list: nothing, a finger, or a spring.
 */
typedef enum {
    GUI_LIST_REST = 0,      /**< Nothing moves it: it stands on a row.      */
    GUI_LIST_FOLLOW,        /**< A finger has it, and the list follows.     */
    GUI_LIST_SETTLE         /**< A spring takes it to a row, or back from an
                              *   end.                                      */
} GuiListPhase;

/**
 * @brief Which motion the list's spring is.
 */
typedef enum {
    GUI_LIST_STEP = 0,      /**< One row of focus: the pad, a tap on a row. */
    GUI_LIST_GLIDE,         /**< A fling, landing on the nearest row.       */
    GUI_LIST_BACK,          /**< Back from a pull past an end (Rubber).     */
    GUI_LIST_GIVE           /**< A block back to its place from a finger's
                              *   pull: list_pull to 0 (Rubber).            */
} GuiListKind;

/**
 * @brief Where the level slide stands.
 */
typedef enum {
    GUI_SLIDE_NONE = 0,     /**< No slide.                                  */
    GUI_SLIDE_OUT,          /**< The old rows leave.                        */
    GUI_SLIDE_IN            /**< The new rows come in.                      */
} GuiSlide;

/**
 * @brief Which of Kody's scenes the face shows.
 *
 * An index into the active pack's scenes (kgui_assets.h), in the pack's
 * order, or KGUI_ASSETS_BUILTIN, the reloj scene compiled in. One is on at a time: the one chosen, which kgui/scene keeps
 * by name, or while none is chosen the one the local hour asks for. Ids are
 * renumbered at every KGUI_ASSETS_EV_RESOLVED: a pack read again is a new
 * table.
 */
typedef uint16_t GuiSceneId;

/**
 * @brief Whether Kody is on the glass, as the face's tick sees it.
 *
 * HIDDEN while the face is off the glass, on its way onto it, or under a
 * card - the times his player stands paused. SEEN the moment the face is
 * uncovered: its load ended (LV_EVENT_SCREEN_LOADED), or the card over it
 * went. The face's next tick wakes him, and he is AWAKE from then on. A
 * scene the face goes on while he is awake - a choice, or the hour's change
 * - puts him back to SEEN, so that the same tick wakes him up in it
 * (gui_face_scene_set()). ASLEEP for as long as the Lock rests (Gui_rest):
 * he stands still on a frame of his scene, nothing is drawn, and leaving Rest
 * puts him back to SEEN (gui_rest_leave()).
 */
typedef enum {
    GUI_KODY_HIDDEN = 0,
    GUI_KODY_SEEN,
    GUI_KODY_AWAKE,
    GUI_KODY_ASLEEP
} GuiKodySight;

/**
 * @brief Which of its looks the empty launcher wears.
 *
 * LOOKING until both lists have answered. Then KODY, and from there the top
 * button or a tap on him takes it to the QR and back, by way of the slide
 * between the two (gui_empty_toggle()). It is the look of the box the
 * screen's binding shows: with rows on the list the box is hidden, whatever
 * this says.
 */
typedef enum {
    GUI_EMPTY_LOOKING = 0,  /**< "Looking for apps": the title alone.        */
    GUI_EMPTY_KODY,         /**< "No apps yet", "Tap Kody to find apps",
                              *   and Kody under them on the glass's bottom
                              *   edge.                                      */
    GUI_EMPTY_LEAVING,      /**< Kody sliding down off the glass, paused.    */
    GUI_EMPTY_QR,           /**< The QR to the app catalogue in his place.   */
    GUI_EMPTY_RETURNING     /**< Kody sliding back up, still paused.         */
} GuiEmptyLook;

/**
 * @brief Which sheet to open, on its way to the state machine.
 *
 * Private to this AO, like the two signals above, and served from the shared
 * pools like every other dynamic event - kgui allocates from the same tiers
 * an app would.
 */
typedef struct {
    QEvt   super;
    uint8_t kind;   /**< A GuiSheet. */
} SheetOpenEvt;

/* The small pool's width is kqp's to know and ButtonEvt is the widest event
 * of this shape it carries, so a private event measured against ButtonEvt is
 * measured against the tier - without the SDK having to name a type that
 * lives above it. */
_Static_assert(sizeof(SheetOpenEvt) <= sizeof(ButtonEvt),
               "SheetOpenEvt must fit the pool ButtonEvt fits");


/* Draw buffers: a tenth of the panel each, in PSRAM, double-buffered so LVGL
 * can render one band while the other is in flight. */
/* A tenth of the panel each, and the divisor is load-bearing: two of these
 * have to fit in INTERNAL RAM, where LVGL renders far faster than in PSRAM.
 * Measured, one full launcher redraw:
 *     2x40KB, both internal -> 37 ms
 *     2x49KB, one spilled   -> 46 ms
 *     2x80KB, one spilled   -> 46 ms
 * Bigger buffers mean fewer flush cycles, which sounds like a win and is
 * not: the moment the second spills to PSRAM half the frames pay the bus.
 * Free internal sits between 80 and 98 KB, so a tenth fits and an eighth
 * does not. Raise this only with the log line below in front of you - it
 * says which memory the buffers actually got. Only for a panel with a single
 * framebuffer: with two, LVGL draws in those. */
#define GUI_BUF_LINES   (KBSP_LCD_V_RES / 10U)
#define GUI_BUF_BYTES   ((size_t)KBSP_LCD_H_RES * GUI_BUF_LINES * 2U)

/* The one list can show both models at once, so its worst case is the sum
 * of theirs: every installed app plus every scanned file, none of them
 * matching. */
#define GUI_ROWS_MAX    (2U * KODE_APP_LIST_MAX)

/* What a row's look, row_lit[], says: the focus is on it (its name is Light
 * Grey), it is any other, or gui_row_paint() has not
 * dressed it yet. */
#define GUI_ROW_PLAIN      0U
#define GUI_ROW_LIT        1U
#define GUI_ROW_UNDRESSED  0xFFU

/* The launcher's two levels (GuiStateEvt::level): the root, which holds the
 * groups and then the apps that belong to none, and one group's apps. */
#define GUI_LEVEL_ROOT   KODE_GUI_LEVEL_ROOT   /* the groups, then the loose apps */
#define GUI_LEVEL_GROUP  KODE_GUI_LEVEL_GROUP  /* the apps of the group in me->group */

/* A group row's selection name: this and the group's name. An app's own name
 * never starts with it, so a group and an app called alike are two rows. */
#define GUI_GROUP_KEY_MARK  '/'

/* How much room a container has to leave its children so the cursor ring can
 * be drawn. The ring is an OUTLINE - #ring_w of 4 plus 2 of outline pad, so
 * 6 px OUTSIDE the pill - and an outline is not clipped by the pill it stands
 * on but by the pill's PARENT. Every container that holds a ringed child is
 * exactly #pill_w wide, which is why the ring lost 6 px on both sides
 * everywhere until this existed. 8 rather than 6 because #space_md is the
 * layout's own unit and the ring only needs a floor, not a fit. */
#define GUI_RING_ROOM   8

/* How far the finger throws a card's page once it lets go, in LVGL's own
 * units (lower is shorter): the sheets' bodies still scroll under LVGL, and
 * land on the row grid with gui_sheet_land(). 12 is about three or four rows
 * from a firm flick - at LVGL's default 50 the same flick ran the length of
 * the page and the row it stopped on was nobody's choice. The Apps list is
 * kgui's own and does not read it (kgui_motion.h). */
#define GUI_LIST_THROW  12

/** A 40 px kit glyph drawn at 56 px in the 112 px header disc: 256 x 56/40. */
#define GUI_GLYPH_DISC_SCALE   358U

/* How far a finger has to travel before LVGL starts a scroll with it: one
 * pixel past the recognizer's claim (KUI_GESTURE_CLAIM_PX), so the recognizer
 * has decided what the press is before a scroll can begin under it. */
#define KGUI_SCROLL_LIMIT_PX  ((uint8_t)KUI_GESTURE_CLAIM_PX + 1U)

/* How long between RSSI refreshes while the settings screen is up: 2 s, the
 * same cadence AO_Power already publishes at. Only that screen asks - nothing
 * polls a radio for a screen nobody is looking at. On the wall clock, like
 * every period here: the tick comes when LVGL is due, so a count of passes
 * is no measure of time. */
#define GUI_SET_RSSI_MS     2000U

/* How often the Wi-Fi sheet looks at the air, COUNTED FROM THE ANSWER: a sweep
 * measures 35 s on this board (kdrv_wifi.h says 38), so a period counted from
 * the question would always be shorter than the thing it paces. One round on
 * entering and one a minute after that, because a sweep takes the C5 off its
 * network's channel for most of its length. On a network, a list that has been
 * answered is left alone for as long as the page stays open, and entering again
 * within the minute asks nothing (the apocrypha's rule, kshell_wifi.c's
 * scan_now()). */
#define GUI_WIFI_SCAN_MS     60000U

/** After a refusal (the link still coming up, the radio busy with the boot's
 *  join round, or with a sweep somebody else asked for) the question goes
 *  again this soon at the latest: nothing was learned. The radio's next
 *  WIFI_STATE_SIG asks sooner, since the end of a join round and the link
 *  coming up both say one (scan_refused). */
#define GUI_WIFI_SCAN_RETRY_MS 10000U

/** The radio answers a sweep it has no time for in the step that receives the
 *  question, so a busy end that comes later than this after the page asked is
 *  another asker's (the console's scan, refused while the page's runs). */
#define GUI_WIFI_BUSY_ANSWER_MS 2000U

/** A scan asked and never answered is given up after this long, and the next
 *  period asks again: the page searches by itself and has no button to search
 *  again (Luismi, 4-nov), so it must never wait on a lost answer. Past the
 *  driver's own ceiling on a sweep and on its last step: asking while the
 *  first is still running is refused with an empty listing, and at 20 s that
 *  was what blanked the page (75dba1c). */
#define GUI_WIFI_SCAN_LOST_MS (KDRV_WIFI_SCAN_TIMEOUT_MS + KDRV_WIFI_SCAN_STEP_TIMEOUT_MS + 3000U)

/** A row goes when this many answered rounds in a row have not heard it: one
 *  missed beacon must not take a network off the list. */
#define GUI_WIFI_SCAN_MISSES 2U

/* How long between temperature reads while the Battery sheet is up: 30 s.
 * Everything else that page shows arrives by itself - AO_Power publishes charge, current and voltage every 2 s and this AO is
 * subscribed - so the temperature is the only thing left to ask for, and a
 * cell whose temperature moved measurably between two 2 s reads would be a
 * board with a bigger problem than a stale row. */
#define GUI_BAT_TEMP_MS     30000U

/* What a gauge reading has to be inside to be believed, in whole degrees.
 * The TS pin reads what is on it, and a board with no thermistor fitted
 * answers -40 C all day (temp_c2 = -80 on the bench unit). A row that
 * confidently reports a temperature nothing measured is worse than no row,
 * so a reading outside the range a lithium cell can be in and still be
 * charged is treated as no reading at all. */
#define GUI_TEMP_MIN_C  (-20)
#define GUI_TEMP_MAX_C  80

/* How long the Bluetooth circle's glyph spends on each half of its blink:
 * 500 ms, so the pair is one second and the glyph pulses at 1 Hz while the
 * radio is advertising. A blink and not a colour, because advertising is a
 * thing that is HAPPENING - it ends by itself when a central arrives or the
 * window closes - and a static ground would have to be taken back down. Only
 * the glyph pulses: the circle's blue stays whole. */
#define GUI_BLE_BLINK_MS     500U
/** @brief The glyph's opacity on the dim half of the blink: still there. */
#define GUI_BLE_DIM_OPA      LV_OPA_40

/* How many remembered networks the sheet can show: the C5's vault keeps eight
 * (KODE_VAULT_NETS_MAX, on the wire kgui does not include), so the number is
 * spelt here and the fill loop stops at whichever runs out first. A vault
 * that grew would show its first eight, not garbage. */
#define GUI_WIFI_SAVED_MAX   8U
#define GUI_SSID_BYTES       33U  /**< A network's name as the rows keep it: the 32 bytes an SSID takes and the terminator. */

#if CONFIG_KODEOS_WIFI
/**
 * @brief Where the keypad's errand stands: a hidden network's name, a
 *        password, or the wait for the join's answer.
 *
 * Kept in me->kbd_stage as a byte, like the other enumerations this AO keeps.
 */
enum {
    GUI_KBD_NONE = 0,   /**< No errand: no keypad is up, or its work is done and the card is closing. */
    GUI_KBD_NAME,       /**< A hidden network's name is being typed. */
    GUI_KBD_PASS,       /**< A password is being typed. */
    GUI_KBD_JOINING,    /**< The join was asked for and its answer is awaited; the text is kept for the answer. */
    GUI_KBD_BLE         /**< The name Bluetooth shows is being typed. */
};

/* How long the keypad waits for the join's answer before it says it could not
 * join: the radio's own wait for an address is 20 s (RADIO_JOIN_MS) and a
 * refused request - the radio was busy with something else - is answered with
 * the state of the network it was already on, which says nothing about this
 * one. Longer than the first by a margin, so a slow join is never called a
 * failure, and short enough that nobody waits for a request that was never
 * taken. A deadline on the wall clock, like every wait here. */
#define GUI_KBD_JOIN_GUARD_MS  30000U

/* What the keypad card says, in the words of the plan's copy. The refusals and
 * the outcomes go to the hint line in the top band, which logs the same
 * words; the text typed is never one of them. */
#define GUI_KBD_PASSWORD     "Password"            /**< What the empty field asks for while a password is typed. */
#define GUI_KBD_NETWORK_NAME "Network name"        /**< What the empty field asks for while a hidden network's name is typed. */
#define GUI_KBD_HIDDEN       "Hidden network"      /**< The Wi-Fi list's last row, and the keypad's title until the name is in. */
#define GUI_KBD_HIDDEN_SUB   "Type its name"       /**< The second line of that row. */
#define GUI_KBD_JOIN         "Join"                /**< The yellow pill while a password is typed. */
#define GUI_KBD_NEXT         "Next"                /**< The yellow pill while a hidden network's name is typed. */
#define GUI_KBD_JOIN_DOT_MS  400U                  /**< One more dot after Joining. */
#define GUI_KBD_JOINED       "Joined"              /**< The outcome of a join that worked. */
#define GUI_KBD_REFUSED      "Could not join"      /**< The outcome of a join that got no answer, or no start. */
#define GUI_KBD_PASS_FULL    "Password is full"    /**< A 64th character was refused. */
#define GUI_KBD_NAME_FULL    "Name is full"        /**< A 33rd character of a name was refused. */
#define GUI_KBD_NEED_PASS    "Type the password"   /**< Join with nothing typed, for a network that has a password. */
#define GUI_KBD_SHORT_PASS   "8 characters at least" /**< Join with fewer than WPA's eight. */
#define GUI_KBD_PASS_MIN     8U                    /**< WPA2 and WPA3 passwords are 8 characters at the least. */
#define GUI_KBD_NEED_NAME    "Type the name"       /**< Next with nothing typed. */
#define GUI_KBD_SCANNING     "Scanning, try again" /**< Join while the radio is still looking for networks: it would refuse. */
#endif

/* What kgui keeps across a reboot: the name of the row the launcher last
 * launched, the zone the face's clock runs in, the auto-lock time, and the
 * scene chosen for the face while one is. kgui's own namespace, because the
 * one AO that applies a setting is the one that stores it (Settings
 * storage.md) - not `kset`, whose keys are spelt in an SDK header the SDK
 * never reads this from, and not the `kapp` provisioning store, which is
 * strings and is listed to operators. */
#define GUI_NVS_NAMESPACE  KGUI_NVS_NAMESPACE
#define GUI_NVS_KEY_LAST   "last"   /* str: the row last launched, or the
                                     * app that ran before the last boot    */
#define GUI_NVS_KEY_ZONE   "zone"   /* str: the zone kgui kept before the system did; read once, then erased */
#define GUI_NVS_KEY_LOCK   "lock"   /* uint32_t record: auto-lock seconds    */
#define GUI_NVS_KEY_SCENE  "scene"  /* str: the scene chosen, by its name;
                                     * absent while the hour picks           */
#define GUI_NVS_KEY_CLOCK  "clock"  /* u8: 1 = the face's 12 h clock;
                                     * absent is 24 h                        */
#define GUI_NVS_KEY_SLEEP  "kody_sleep" /* uint32_t record: seconds without
                                     * input before the Lock rests, 0 for
                                     * never; absent while it follows the
                                     * auto-lock                             */
#define GUI_NVS_KEY_RECENTS "recents" /* str: the apps last run, by project
                                     * name, one a line, the latest first,
                                     * KGUI_SHELF_MAX at most (kgui_shelf.h) */
#define GUI_NVS_KEY_HOUR_SCENE "scene_hr" /* blob: the scene the hour drew and which hour */
/* The two interface settings - haptic_ui and usb_awake - are bytes in the same namespace, and their keys are spelt in
 * kgui_prefs.h. */

/** @brief What `config key="scene"` calls no choice at all: the
 *         word that forgets the scene chosen, and what the log says of a
 *         scene the hour picked. No scene goes by it (kui_pack.h's rule for
 *         a scene's name allows it, so a pack that names one has a scene
 *         `config` can reach only through the pad and the swipe). */
#define GUI_SCENE_AUTO  "auto"

/** @brief The longest scene name kgui/scene is read with, terminator aside:
 *         a pack's scene names are no longer (KUI_PACK_NAME_MAX). */
#define GUI_SCENE_NAME_MAX  KUI_PACK_NAME_MAX

/** @brief The longest time-zone string kgui/zone keeps, terminator aside. */
#define GUI_ZONE_MAX  32U
_Static_assert(GUI_ZONE_MAX == KODE_CONFIG_VALUE_MAX,
               "kgui's copy of the zone holds any zone AO_Boot answers");

/** @brief The zone a board with nothing stored runs in: the board's own UTC,
 *         and the list's row for it (s_zones). */
#define GUI_ZONE_UTC  "UTC0"

/**
 * @brief One zone of the list: what its row and About's Time zone row call
 *        it, and the POSIX TZ string the clock runs in.
 */
typedef struct {
    const char *label;  /**< The list row's name, About's second line, and
                          *   the log's word.                                */
    const char *tz;     /**< The POSIX TZ string, at most GUI_ZONE_MAX.     */
} GuiZone;

/**
 * @brief One auto-lock time of the list: how long it is, what its row and
 *        the Screen sheet's Auto-lock row call it, and what the door it
 *        leads to says in the log.
 */
typedef struct {
    uint32_t    s;      /**< Seconds without input before the face comes
                          *   back; 0 is never.                              */
    const char *label;  /**< The list row's name, the Screen row's second
                          *   line, and the log's word.                      */
    const char *why;    /**< What the auto-lock's door line says asked for
                          *   it (gui_door_log()).                           */
} GuiLock;

/** @brief Which `assets_*` console function a GuiAssetsCmdEvt carries. */
typedef enum {
    GUI_ASSETS_INFO = 0,  /**< assets_info.   */
    GUI_ASSETS_CHECK,     /**< assets_check.  */
    GUI_ASSETS_RELOAD,    /**< assets_reload. */
    GUI_ASSETS_BEGIN,     /**< assets_begin.  */
    GUI_ASSETS_COMMIT,    /**< assets_commit. */
    GUI_ASSETS_UPDATE,    /**< assets_update. */
    GUI_ASSETS_TRY        /**< assets_try.    */
} GuiAssetsCmd;

#define GUI_ASSETS_ARG_MAX 128U  /**< An `assets_*` argument, terminator included: a medium, a count or a pack URL. Its own number since KODE_FLASH_SRC_MAX grew to 257 for install URLs, which no longer fits the medium pool beside the ticket. */

/**
 * @brief An `assets_*` console function on its way to the state machine.
 *
 * A copy of its argument (rule 7): a medium, a
 * byte count, a URL or a file name, checked by the run for its form and by
 * kgui_assets for what it names.
 */
typedef struct {
    QEvt     super;
    uint32_t ticket;                   /**< The function's (function_ticket()). */
    uint8_t  cmd;                      /**< A GuiAssetsCmd.            */
    char    arg[GUI_ASSETS_ARG_MAX];   /**< The argument, or empty.    */
} GuiAssetsCmdEvt;

_Static_assert(sizeof(GuiAssetsCmdEvt) <= sizeof(ConsoleLineEvt),
               "GuiAssetsCmdEvt must fit the pool ConsoleLineEvt fits");

/* How long the card's slide takes (gui_sheet_slide()). The duration is set by
 * the frame cost, not by taste: a slide that repaints the glass every step costs
 * a measured 36-73 ms a repaint (the PPA that would change them is off), so a
 * "smooth" 220 ms was three to six frames and read as slow motion on the
 * bench - the owner's words. 140 ms is two to four frames: a flick, over
 * before the eye asks for smoothness. The flash-write takeover stays a hard
 * cut on purpose: urgency is its message, and a loading screen sliding in
 * politely would say the opposite. */
#define GUI_SCR_ANIM_MS  120U

/** @brief The same sheet going down and out: kshell's KS_T_MOVE_OUT, easing in. */
#define GUI_SCR_OUT_MS   100U

/** @brief How long the face's door, a folder and a settings page with no circle take: kshell's KS_T_MOVE since 14-oct. */
#define GUI_PAGE_ANIM_MS 120U

/** @brief How long the date stands under the hour on waking (the apocrifa's 6 s, in 33 ms steps). */
#define GUI_DATE_SHOW_MS 5940U

/** @brief home_way: no swipe asked for a side; the way back mirrors how the face left. */
#define GUI_HOME_AS_CAME    0U
#define GUI_HOME_FROM_LEFT  1U   /**< home_way: the face comes in from the left (a swipe right on Apps). */
#define GUI_HOME_FROM_RIGHT 2U   /**< home_way: the face comes in from the right (a swipe left on Apps' root). */

/** @brief The same page going back: kshell's KS_T_MOVE_OUT. */
#define GUI_PAGE_BACK_MS 100U

#define GUI_GROW_IN_MS   198U  /**< How long a settings page takes to grow out of its circle: kshell's level zoom, 7 frames of 33 ms. */
#define GUI_GROW_OUT_MS  231U  /**< How long it takes to shrink back into it: 8 frames. */

/** @brief How solid an object is on its one frame of fade, when a level's
 *         pictures could not be taken: half. */
#define GUI_FADE_OPA     LV_OPA_50
/** @brief The longest a frame of fade waits to be drawn, in milliseconds,
 *         before the motion goes on without it: a glass that draws nothing
 *         must not hold a door. */
#define GUI_FADE_MAX_MS  100U

#define GUI_META_PASSES    2U    /**< The passes of the folders' chain: the rows never answered, then the rest. */
#define GUI_META_RETRY_MS  500U  /**< How long after a folder answered busy it is asked again. */
#define GUI_DESC_TRIES     6U    /**< How many times a refused manifest is asked again before the file is shown as it is. */
#define GUI_META_NAMES_MAX 4U    /**< How many names the line that says what the list did not wait for carries. */
#define GUI_META_LOG_MAX   96U   /**< The room for those names, in characters. */

/** @brief No button woke the Lock: wake_btn while no press is being swallowed. */
#define GUI_WAKE_BTN_NONE  0xFFU

/** @brief How long a flush may take before the frame is written off.
 *
 * A flush is 10-50 ms in normal running and the worst render measured on this
 * board was 51 ms, so this is ten times the worst observed: far too long to
 * fire by accident, far shorter than a person deciding the device is dead.
 */
#define GUI_FLUSH_TIMEOUT_MS  500U

#if CONFIG_KODE_LOWPOWER
/** Why a round is refused while a flash write's card is up. */
#define GUI_LP_WHY_WRITE   "write in flight"
/** Why a round is refused while the factory reset's wait is up. */
#define GUI_LP_WHY_RESET   "factory reset"
/** Why a round that comes before the glass is up is refused. */
#define GUI_LP_WHY_START   "starting"
/** Why a round for ASLEEP is refused at Rest while Kody has not settled, or
 *  a sleep at Rest that did not happen holds the next one back. */
#define GUI_LP_WHY_REST    "rest not settled"
/** Past the 30 minutes at Rest, so the board that wakes for the count finds
 *  them gone. */
#define GUI_REST_WAKE_SLACK_MS 200U
#if CONFIG_KODE_TEST_DOT
/** Why a round is refused while the E5 test has the glass. */
#define GUI_LP_WHY_TEST_DOT "E5 test"
#endif
#endif

/* The motions the debug log times (kgui_frames.h), by the name its line
 * prints. */
#define GUI_MOTION_SHEET_IN            "sheet in"           /**< The sheet's card slides up. */
#define GUI_MOTION_SHEET_OUT           "sheet out"          /**< The sheet's card slides away. */
#define GUI_MOTION_LEVEL               "level"              /**< The list slides out and back for a new level. */
#define GUI_MOTION_STEP                "step"               /**< The list catches up with the selection, a row at a time. */
#define GUI_MOTION_GLIDE               "glide"              /**< A fling lands on a row. */
#define GUI_MOTION_RUBBER              "rubber"             /**< The list comes back from a pull past its end. */
#define GUI_MOTION_LIST_DRAG           "list drag"          /**< The list follows a finger. */
#define GUI_MOTION_LAUNCH              "launch"             /**< An installed app's icon flies, the Ring closes and the glass goes black. */
#define GUI_MOTION_CURTAIN             "curtain"            /**< The settings curtain, down or up. */
#define GUI_MOTION_FACE_CURTAIN        "face curtain"       /**< The face curtain: the lock, down, or the unlock, up. */
