/**
 * @brief The pages that open over another page and the page each goes back
 *        to: More's six pages (Screen, Battery, Time zone, Kody, Self-test,
 *        About), Screen's auto-lock times, and the Wi-Fi page's keypad, which
 *        is no list and goes back the same way (to the row that opened it:
 *        me->kbd_door, not the door written here).
 *
 * ONE MECHANISM FOR ALL. A page opens only in place over its own page
 * (gui_sheet_open_taken()), and every way back - the bottom button, a drag
 * down on the card's header, a pick - turns the card back into that page,
 * ringed on the row that opened the list (gui_sheet_body()).
 */
static const GuiListPage s_list_pages[] = {
    { GUI_SHEET_BAT,      GUI_SHEET_MORE,   (uint16_t)GUI_TAG_MORE_BAT,
      "Settings" },
    { GUI_SHEET_ZONE,     GUI_SHEET_MORE,   (uint16_t)GUI_TAG_MORE_ZONE,
      "Settings" },
    { GUI_SHEET_TIME,     GUI_SHEET_MORE,   (uint16_t)GUI_TAG_MORE_TIME,
      "Settings" },
    { GUI_SHEET_WIFI,     GUI_SHEET_MORE,   (uint16_t)GUI_TAG_MORE_WIFI,
      "Settings" },
    { GUI_SHEET_BLE,      GUI_SHEET_MORE,   (uint16_t)GUI_TAG_MORE_BLE,
      "Settings" },
    { GUI_SHEET_KODY,     GUI_SHEET_MORE,   (uint16_t)GUI_TAG_MORE_KODY,
      "Settings" },
    { GUI_SHEET_TEST,     GUI_SHEET_MORE,   (uint16_t)GUI_TAG_MORE_TEST,
      "Settings" },
    { GUI_SHEET_ABOUT,    GUI_SHEET_MORE,   (uint16_t)GUI_TAG_MORE_ABOUT,
      "Settings" },
    { GUI_SHEET_AUTOLOCK, GUI_SHEET_MORE,   (uint16_t)GUI_TAG_SCREEN_LOCK,
      "Settings" },
    { GUI_SHEET_KEYPAD,   GUI_SHEET_WIFI,   (uint16_t)GUI_TAG_WIFI_HIDDEN,
      "Wi-Fi" },
};

/**
 * @brief What one press of left or right is worth on a value row.
 *
 * Five percent: twenty steps end to end, which is a pad held down for about
 * two seconds and a single press that is visibly a change rather than a
 * rounding error.
 */
#define GUI_LEVEL_STEP     5U

/**
 * @brief How often a finger dragging a value row is allowed to move the level.
 *
 * Fifty milliseconds. A drag is sampled every touch report and the panel's
 * owner is on the far side of a level change, so applying every sample would
 * spend the whole of this AO's step on a gesture that moves one capsule.
 * Twenty applications a second is faster than an eye reads the number and
 * slower than the glass can be dragged across, which is the definition of
 * live. The press and the release are never throttled: the first is the
 * tap's own answer and the last is the value the finger stopped on.
 */
#define GUI_LEVEL_DRAG_MS  50U

/**
 * @brief The dimmest the glass may be driven from the sheet.
 *
 * Not zero, and this is the whole point: brightness is the one level whose
 * bottom end takes away the screen the control is drawn on. Ten percent (kshell's
 * floor) is dark enough for a night desk and still readable, so the pad can always
 * find its way back up. The console's `brightness` verb keeps the full range -
 * an operator who asks for zero over the wire has another way back.
 */
#define GUI_BRIGHT_MIN_PCT KGUI_CC_LEVEL_MIN_PCT

/**
 * @brief The key of the volume, AO_Audio's own setting (`config key="vol"`).
 *
 * The level is kept where the console's `config` keeps it: this AO asks the
 * owner by event, and the owner applies and stores. kgui's namespace holds
 * nothing of it.
 */
#define GUI_VOL_KEY        "vol"

/** @brief The code of the digit zero: the answer's words are digits (gui_vol_answer()). */
#define GUI_ASCII_ZERO     48U

/**
 * @brief The sequence numbers this AO puts on its requests of `vol`.
 *
 * The console numbers its own from 1 and only takes the answer to the one in
 * flight; the top bit keeps these two out of its way, and says in the answer
 * which of the two it is.
 */
#define GUI_VOL_SEQ_READ   0x80000001U   /**< Ask what the volume is. */
#define GUI_VOL_SEQ_SET    0x80000002U   /**< Set it and keep it. */
#define GUI_ZONE_SEQ_BASE  0x80000100U   /**< kgui's own `zone` requests start here: the top half, which the console's counter never reaches. */
#define GUI_ZONE_SEQ_MASK  0x0000FFFFU   /**< How far they count before they wrap. */

#if CONFIG_KODEOS_BLE_PAIRING_PASSKEY
/**
 * @brief How long the sheet's outcome stays readable before it leaves.
 *
 * Long enough to read three words, short enough that nobody waits for it.
 * A deadline on the wall clock, read across its wrap, so it always releases:
 * a wait that can fail to release is worse than the bug it prevents.
 */
#define GUI_PAIR_HOLD_MS     1200U
#define GUI_PAIR_OK_WORD     "Paired"      /**< The outcome of a pairing that went through, and the name of its screen. */
#define GUI_PAIR_NO_WORD     "Not paired"  /**< The name of the screen of a pairing that did not. */
#define GUI_PAIR_TEXT_Y      240           /**< Where the words under a pairing's code begin. */
#endif

/* Where the battery's icon and bar change colour, and they are two different
 * sentences rather than two numbers: LOW is "plan to charge it" - an orange
 * while there is still a comfortable margin - and CRIT is "this is about to
 * end", the red or rose that means it. Charging outranks both: a
 * cell that is filling is not a problem whatever it currently holds. */
#define GUI_SET_BAT_LOW_PCT   25U
#define GUI_SET_BAT_CRIT_PCT  KGUI_BAT_CRIT_PCT

/* What bat_state carries, and what gui_bat_grade() turns into a colour: a
 * GRADE, not a percentage. The battery sheet's bar is how much is left, a
 * level like the Screen's; this is what that much means, and the battery
 * page's header glyph tells it by its colour alone. */
#define GUI_SET_BAT_OK    0
#define GUI_SET_BAT_LOW   1
#define GUI_SET_BAT_CRIT  2
#define GUI_SET_BAT_CHG   3

/* ---- The AO -------------------------------------------------------------- */

/**
 * @brief The control centre's controls.
 *
 * kshell's control centre as the agreed simulator lays it out: three circles
 * in the top row, the battery and Turn off under the first and the last, and
 * the brightness and volume levels under them. This enum indexes set_ctl[]
 * (gui_settings_move() is the pad's map); it is written with designated
 * initialisers wherever it is tabled, so a reorder cannot misalign them
 * silently.
 *
 *     Wi-Fi     Bluetooth     More
 *     Battery                 Turn off
 *     [ brightness level ----------- ]
 *     [ volume level --------------- ]
 *
 * The battery's circle shows the charge as a liquid and opens the Battery
 * page, as a radio's circle opens its own.
 */
typedef enum {
    GUI_SET_WIFI = 0,
    GUI_SET_BLE,
    GUI_SET_MORE,
    GUI_SET_OFF,
    GUI_SET_BAT,
    GUI_SET_LEVEL,
    GUI_SET_VOLUME,
    GUI_SET_COUNT
} GuiSetCtl;


/**
 * @brief What one control of the control centre, or one row of More, looks
 *        like, and what its page is called.
 *
 * ONE table for both readers: the control and the page it opens cannot
 * disagree about which glyph or which name the thing is - which is exactly
 * what two tables would eventually let them do.
 */
typedef struct {
    lv_color_t  col;     /**< The page's colour: what a radio's rows wear
                           *   when it is on, and Bold Yellow for a level;
                           *   Soft Black, the ink of a disc's glyph, else. */
    const void *glyph;   /**< What rides in the circle or the row's disc. */
    const char *title;   /**< The name a reader sees on the page.         */
} GuiSetLook;

/**
 * @brief What an answer is to the screen it stands on: the brand's three
 *        grounds for an action.
 *
 * One role per screen at most is PRIMARY: it is the one yellow pill, and a
 * pill that cannot act is not it.
 */
typedef enum {
    GUI_ACT_PRIMARY = 0,   /**< What the screen is for: Bold Yellow.        */
    GUI_ACT_SECONDARY,     /**< An answer beside it: Light Grey.            */
    GUI_ACT_TERTIARY,      /**< One to keep out of the way: the muted dark. */
    GUI_ACT_DANGER,        /**< An ending: Danger red.                      */
    GUI_ACT_DISABLED       /**< One that cannot act now: the resting grey.  */
} GuiActRole;

/**
 * @brief THE FACE A ROW WEARS: everything the launcher draws about an app
 *        that is not its identity.
 *
 * Resolution is field by field, first source that has it (the order is at
 * https://docs.kode.diy/sdk/kdrv/apps), and it is done by WRITING: the
 * entry's own sources seed the face the moment they are known
 * (gui_face_seed(), from
 * the manifest chain and the apps-region listing), and the data folder's
 * answer overwrites whichever fields it carries when APPDATA_FIELDS_SIG
 * lands. There is no second resolver at paint time, because a second
 * resolver is a second opinion: repaint_list() reads this struct and draws
 * exactly what it says.
 *
 * What it does NOT hold is the identity. A folder may rename an app's
 * label and repaint its capsule; the project name behind the row is the
 * binary's and nothing else's (gui_row_name()).
 *
 * The icon is not here: 12 KB does not belong in an entry, and a PSRAM
 * slot per entry holds it instead (me->icon_slot). What is here is whether
 * that slot is worth drawing.
 */
typedef struct {
    char       name[KODE_APP_DISPLAY_MAX];      /**< folder > manifest > project.   */
    char       category[KODE_APP_CATEGORY_MAX]; /**< folder > table > manifest.     */
    char       version[KAPP_DATA_VERSION_MAX];  /**< folder > the image's own.      */
    char       description[KAPP_DATA_DESC_MAX]; /**< The folder's alone.            */
    lv_color_t color;                           /**< The app's own colour.          */
    bool       color_ok;                        /**< ...and the folder gave it.     */
    bool       icon_ok;                         /**< The slot holds a whole icon.   */
    uint8_t    icon_status;                     /**< AppDataIconStatus, for the log.*/
    uint8_t    json_status;                     /**< kapp_json_status_t, ditto.     */
    bool       asked;                           /**< The folder question went out.  */
    uint8_t    icon_parts;                      /**< Bitmask of the thirds landed.  */
    bool       settled;                         /**< Its folder has answered, busy not counted; kept by a rescan. */
    bool       known;                           /**< Its category is known: all the root asks of a row (gui_meta_release()). */
    bool       shown;                           /**< The list shows this row (gui_meta_release()); kept by a rescan. */
    bool       retry;                           /**< The folder answered busy: asked again (gui_meta_retry()). */
} GuiFace;

#define GUI_APP_NAME_MAX  32U  /**< An installed app's project name: esp_app_desc_t.project_name. */

/** One .bin file as the GUI knows it (its own copy; see storage_list_request). */
typedef struct {
    char     name[KODE_APP_FILE_MAX];
    uint32_t size;
    bool     from_sd;
    /* Filled later, one STORAGE_DESC_RSP_SIG at a time. Empty means "not
     * asked yet, or unmanifested" - the launcher treats both as Other,
     * because to a reader they look the same and neither is an error. */
    char     display[KODE_APP_DISPLAY_MAX];
    char     category[KODE_APP_CATEGORY_MAX];
    char     project[32];   /**< For the exact install match. */
    bool     asked;         /**< A question is out, or was answered. */
    bool     retry;         /**< The manifest was refused and is asked again (gui_meta_retry()). */
    uint8_t  tries;         /**< How many refusals this file has had since its listing. */
    GuiFace  face;          /**< What the row draws; see GuiFace. */
} GuiEntry;

/**
 * @brief One installed app, as the GUI knows it (its own copy; see
 *        appmgr_list_request). Same fields AppEntryEvt carries - size and
 *        seq included, though the pill only shows the name; they are what the
 *        wire actually sends and a future use is cheaper than a second
 *        struct. display/category ride along the same way, from the app's
 *        own manifest. The offset is what names the app that ran before this
 *        boot (gui_last_follow_offset()).
 */
typedef struct {
    char     name[GUI_APP_NAME_MAX];
    char     version[16];
    uint32_t size;
    uint32_t seq;
    uint32_t offset;       /**< Where its image sits in the apps region: what boot_app_offset() answers with. */
    char     date[KODE_APP_DATE_MAX]; /**< When its image was built, as the compiler wrote it; "" when the image does not say. */
    char     display[KODE_APP_DISPLAY_MAX];
    char     category[KODE_APP_CATEGORY_MAX];
    GuiFace  face;          /**< What the row draws; see GuiFace. */
} InstalledEntry;

/** @brief Which model a row resolves through. */
typedef enum {
    GUI_ROW_INSTALLED,   /**< idx into installed[]. */
    GUI_ROW_FILE,        /**< idx into entries[]. */
    GUI_ROW_GROUP,       /**< idx into groups[]: a group at the root, with no app of its own. */
} GuiRowKind;

/**
 * @brief One row of the launcher: which model it came from, and where in it.
 *
 * rows[] is rebuilt by repaint_list() in the same pass that creates the
 * pills, so a row index (what a pill's click callback carries, what sel_idx
 * holds) always resolves through here to an entry that exists - the models
 * only change in handlers that repaint before returning.
 */
typedef struct {
    GuiRowKind kind;
    uint8_t    idx;      /**< Index into installed[] or entries[], per kind. */
    uint32_t   id;       /**< The row's identity, a hash of its kind and its
                          *   name: what a repaint compares to learn whether
                          *   the rows are the same as the last pass left. */
} GuiRow;

/** @brief How the rows the models hold stand against the wait for their metadata. */
typedef struct {
    uint8_t total;     /**< Rows the models would show if none were held back. */
    uint8_t settled;   /**< Of them, those whose folder has answered. */
    uint8_t known;     /**< Of them, those whose category is known. */
    uint8_t held;      /**< Of them, those the list does not show yet. */
} GuiMetaCount;

/**
 * @brief The apps the models would show, flat, and the level made from them.
 *
 * Taken once, in PSRAM (gui_lists_alloc()), because the category lists alone
 * are KGUI_GROUP_CATS_LEN bytes for each of GUI_ROWS_MAX apps. It is scratch
 * for one pass of gui_view_make() and keeps nothing between passes.
 */
typedef struct {
    char             cats[GUI_ROWS_MAX][KGUI_GROUP_CATS_LEN]; /**< Each app's category list. */
    GuiRow           cand[GUI_ROWS_MAX];    /**< The apps, as rows of their models. */
    GuiRow           view[GUI_ROWS_MAX];    /**< The level's rows. */
    kgui_group_row_t grows[GUI_ROWS_MAX];   /**< The root, as the group model made it. */
    uint8_t          member[GUI_ROWS_MAX];  /**< A group's apps, as places in cand[]. */
} GuiFlat;

typedef struct {
    QActive   super;
    QTimeEvt  tick;

    lv_display_t *disp;
    lv_indev_t   *indev;


    /* Touch state, written by TOUCH_EVT_SIG and read by the LVGL input
     * callback - both on this AO's thread, so no synchronisation. */
    int16_t   touch_x;
    int16_t   touch_y;
    bool      touch_pressed;

    /* The scanned files, KODE_APP_LIST_MAX of them, in PSRAM: taken once by
     * gui_lists_alloc() and never freed, because at 64 rows the two lists
     * would cost about 45 KB of an internal RAM that has none to spare.
     *
     * A listing comes in pages, posted to this AO alone because it asked,
     * and every entry carries its place in it (`pos`): entry `pos` is stored
     * at index `pos`, and pos 0 begins a new listing. That is what makes a
     * new listing replace the last one rather than append to it, and what
     * makes a page asked twice change nothing.
     *
     * Nothing else empties entries[]: gui_request_list() deliberately does
     * not, so the launcher keeps the list it is showing for as long as the
     * card takes to answer. */
    GuiEntry *entries;
    uint8_t   entry_count;
    /* An entry has arrived since the last end marker. An end marker with
     * none behind it closes an empty listing, which empties the model - the
     * one case pos 0 cannot announce. */
    bool      entry_since_end;
    /* This AO asked for a page past the first and is waiting on it: an empty
     * answer then is the end of a listing, not an empty one. */
    bool      list_paging;
    /* The skip the last page was asked with. A page that ends with `more`
     * and leaves entry_count here brought nothing, and is not asked again:
     * every page asked must move the count, so a listing ends. */
    uint8_t   list_from;
    /* The listing had more files than KODE_APP_LIST_MAX: said once, in the
     * log, when its last page ends. */
    bool      files_cut;

    /* The installed apps - what an installed pill boots, and the front half
     * of the one list. Filled by APP_ENTRY_SIG / APP_LIST_END_SIG, the same
     * pages, the same `pos` and the same PSRAM as entries[] above. */
    InstalledEntry *installed;
    uint8_t         installed_count;
    bool            installed_since_end;  /**< As entry_since_end.       */
    bool            apps_paging;          /**< As list_paging.           */
    uint8_t         apps_from;            /**< As list_from.             */

    /* Whether each half of the list has answered at least once since boot.
     * An empty launcher has two things it could say and only one of them is
     * true while a scan is still out: the label alone ("Looking for apps")
     * until both have answered, and once they have, Kody under "No apps
     * yet" - or the QR and its address, on a board where he could not be
     * made. Both halves reach repaint_list() on their own, and the apps
     * region answers in milliseconds where the card takes seconds - so
     * without this the empty state would go up on the first answer and be
     * taken down again by the second. The same pair, through
     * gui_lists_settled(), also
     * holds the first repaint back until the whole list exists, so a boot
     * does not paint the installed pills alone and then the files onto
     * them. Never cleared once set: a rescan of an empty launcher should
     * leave the card where it is rather than blink it. */
    bool      list_answered;
    bool      apps_answered;

    /* A listing round this AO asked for and has not heard the end of: each
     * half is set as its question goes out (gui_request_list(),
     * gui_request_installed()) and cleared by its own end marker, and the
     * pair is believed for GUI_LIST_ROUND_MS at most - gui_listing_out().
     * What it decides is whether the face's door into the launcher asks both
     * lists again: not while a round is still out, which is the boot's own
     * round for the first seconds of every boot. Two rounds at once would
     * put two manifest questions in flight, and AO_Storage answers one. */
    bool      list_out;
    bool      apps_out;
    uint32_t  list_out_ms;   /**< khal_time_ms() when the last question
                               *   went out. */

    /* THE ICON SLOTS: one 12 KB piece of PSRAM per ENTRY, and a header
     * pointing at it. Per entry rather than per row, because a row is
     * rebuilt on every repaint while the thing an icon belongs to is not:
     * entries[i] takes slot i, installed[i] takes slot KODE_APP_LIST_MAX+i,
     * and gui_entry_slot() is the one place that arithmetic lives.
     *
     * Taken once in ui_build() for the whole ceiling and never freed. 128
     * slots is 1.5 MB of the board's 31 MB (the row copies below add 1 MB),
     * and khal_alloc_psram() never falls back - an allocator whose placement
     * is a decision rather than a race is one you do not churn (khal_system.h
     * says why).
     *
     * The three chunks of an icon land here by seq as they arrive, so a
     * slot is a half-built picture for as long as the conversation runs.
     * face.icon_ok is what says it may be drawn, and only APPDATA_END_SIG
     * sets it. */
    uint8_t        *icon_slot[GUI_ROWS_MAX];
    lv_image_dsc_t  icon_dsc[GUI_ROWS_MAX];

    /* Whose folder is being asked about right now, or empty. One question
     * in flight at a time, exactly as the manifest chain above works, and
     * for a stronger reason: an icon is three jumbo blocks out of four, so
     * two conversations at once would be the pool. It is also what
     * APPDATA_END_SIG reads - the end marker is bare, and this is what says
     * whose end it is. */
    char      appdata_project[32];

    /* THE LIST WAITS FOR ITS METADATA. A row is settled when its folder has
     * answered (GuiFace.settled), and the list shows nothing - no rows, no
     * light, no bar - until every row is, or KGUI_META_WAIT_MS after the
     * last listing ended; then all of it appears at once, in one short fade
     * (gui_meta_release(), gui_reveal_begin()). From then a rescan never
     * hides it again: a row that was there stays, and a new one is added
     * when it has settled or its own wait has run out. */
    kgui_meta_t meta;         /**< The wait: whether the list has appeared, and the clock of it. */
    uint8_t   meta_held;      /**< Rows still held back, as the last pass counted them. */
    bool      meta_retrying;  /**< A folder answered busy and is asked again at meta_retry_ms. */
    uint32_t  meta_retry_ms;  /**< khal_time_ms() when that busy answer came. */
    bool      reveal_on;      /**< The list's fade in is running. */
    uint32_t  reveal_ms;      /**< khal_time_ms() when it began. */

    /* The one list, as last painted: what each pill means (rows[]) and the
     * pill itself (pills[]), index-aligned. row_count plus the rows still
     * held back is what kgui_subject_app_count shows. */
    GuiRow    rows[GUI_ROWS_MAX];
    lv_obj_t *pills[GUI_ROWS_MAX];
    uint8_t   row_count;

    /* THE SELECTION: the pill the pad's cursor sits on, or the last one
     * tapped - -1 / empty when the list is. gui_select() is the only place
     * that moves it: it repaints the two rows the move is about (the colour
     * IS the cursor) and captures sel_name from the row, which is what lets
     * gui_resync_selection() survive a repopulation that would otherwise
     * strand a plain index (a console `app erase` while the list is up).
     * int8_t, not uint8_t: "no selection" needs a value outside the valid
     * range. */
    int8_t    sel_idx;
    char      sel_name[KODE_APP_FILE_MAX];

    /* THE LEVEL. The launcher shows its root, the groups and then the apps
     * that belong to none (kgui_group_root()), or one group's apps
     * (kgui_group_members()). A group is a view of the apps' first category,
     * never data: it is derived in the pass that builds rows[], so an empty
     * group cannot exist. group is the truth about where the launcher is;
     * when the apps of it are gone the pass falls back to the root.
     *
     * The selection is kept by name for each level: sel_name for the level on
     * the glass, and sel_root for the root while a group is open, so going
     * back finds the group's row again. A group's row is named by its key
     * (gkey[]), which no app's name starts with. */
    uint8_t         level;                       /**< GUI_LEVEL_ROOT or GUI_LEVEL_GROUP. */
    char            group[KGUI_GROUP_NAME_MAX];  /**< The open group, by name; empty at the root. */
    char            sel_root[KODE_APP_FILE_MAX]; /**< The root's selection while a group is open. */
    kgui_group_t    groups[KGUI_GROUP_MAX];      /**< The root's groups, as the last pass made them. */
    char            gkey[KGUI_GROUP_MAX][KGUI_GROUP_NAME_MAX + 1U]; /**< Each group's row name. */
    uint8_t         group_count;                 /**< How many groups the root has. */
    bool            pending_back;                /**< A swipe's intent, to go back, applied on
                                                  *   the next tick: the claim is taken while the indev holds the
                                                  *   press, and repainting from there deletes the very objects the
                                                  *   indev is walking, so it only records what to do. */
    GuiFlat        *flat;                        /**< The rows the models would show, flat, in PSRAM. */
    bool            pad;                         /**< The pad is the input in use: the focus rings are drawn. */
    bool            ring_woke;                   /**< The last button press is the one that brought the focus rings back
                                                  *   (gui_btn_track(), gui_ring_hidden_press()). */
    GuiSlide        slide;                       /**< The level change is mid-slide: the rows are on their way
                                                  *   out, or the new ones on their way in. A second change
                                                  *   arriving now cannot wait for it - see gui_level_change(). */
    kui_spring_t    slide_spring;                /**< The slide's spring, in pixels. */
    float           slide_x;                     /**< How far the rows stand from where they rest, sideways. */

    /* The screen's widgets this AO holds a pointer to: the containers the
     * data-dependent rows go into, and the empty state's pieces
     * whose visibility no subject can decide. Everything else is reached by
     * subject. */
    lv_obj_t *app_list;
    lv_obj_t *tp_target;            /**< The touch test's target, moved per prompt. */
    lv_obj_t *empty_cta;            /**< The empty state's QR and the address
                                      *   under it, as one box: what an empty
                                      *   launcher offers instead of a list.
                                      *   NULL when the screen has no slot for
                                      *   it, or the code would not encode. */
    lv_obj_t *empty_tap;            /**< "Tap Kody to find apps", under the
                                      *   empty state's title while Kody
                                      *   stands below it.
                                      *   NULL when the screen has no slot for
                                      *   it. */

    /* KODY ON THE EMPTY LAUNCHER. A second player, made in ui_build() as a
     * floating child of empty_box and kept - NULL when it could not be made,
     * or could not play, and then the empty state is the QR alone - and
     * which look the empty state wears. */
    lv_obj_t    *empty_kody;        /**< The player, 410 x 369.              */
    GuiEmptyLook empty_look;        /**< See GuiEmptyLook.                   */
    bool         empty_loaded;      /**< duda is on the player: played once,
                                      *   the first time he was needed
                                      *   (gui_empty_load()).                */
    bool         empty_tapped;      /**< A tap on Kody, for the launcher's
                                      *   tick to answer (gui_empty_tick()),
                                      *   never the callback that saw it.    */

    /* THE LIST. The launcher's list is a box of rows in a window, and the
     * box moves by one number: list_u, the selection coordinate in pixels. A
     * row is at rest when list_u is its pitch times its index, the content's
     * offset follows from it (kgui_rows_scroll()), the ring stands at it
     * (kgui_rows_light_y()) and the row nearest the focus line is the one the
     * focus is on and wears the focused name (gui_light_row()). A finger
     * takes the list (GUI_LIST_FOLLOW) or a spring does (GUI_LIST_SETTLE);
     * the tick places the box (gui_list_tick()), and a placement selects the
     * row that stands nearest the focus line when the motion is a finger's or
     * a fling's - a step has selected its row at the press, and the ring and
     * the name reach it with u. */
    kgui_list_t   list;                     /**< The box and the focus ring.  */
    uint8_t       row_lit[GUI_ROWS_MAX];    /**< Each row's look: GUI_ROW_LIT
                                              *   for the row the focus is on,
                                              *   GUI_ROW_PLAIN, or
                                              *   GUI_ROW_UNDRESSED for a row
                                              *   not drawn yet.             */
    int32_t       list_h;                   /**< The window's height.         */
    GuiListPhase  list_phase;               /**< Who has the list.            */
    GuiListKind   list_kind;                /**< Which motion the spring is.  */
    int16_t       list_target;              /**< The row a settling list
                                              *   lands on, -1 for none.      */
    float         list_u;                   /**< The selection coordinate the
                                              *   list stands at, as drawn:
                                              *   past an end by what the
                                              *   rubber shows.              */
    float         list_pull;                /**< How far a block stands off its
                                              *   place under a finger, as
                                              *   drawn; 0 for any other list
                                              *   (gui_list_block()).        */
    int32_t       list_grab_y;              /**< The finger's row at the
                                              *   claim.                     */
    float         list_grab_raw;            /**< Where the finger would have
                                              *   u at the claim, with no
                                              *   rubber at the ends.        */
    bool          list_caught;              /**< A finger caught the list in
                                              *   flight and still holds it.  */
    bool          list_past;                /**< The finger holds the list past
                                              *   an end: the thud was played.*/
    bool          list_press_moving;        /**< The press that is on landed
                                              *   on a list in flight: its
                                              *   click acts on nothing.     */
    uint32_t      list_placed_ms;           /**< khal_time_ms() when the
                                              *   launcher's motions last
                                              *   placed their objects: the
                                              *   box and the slide.         */
    kui_spring_t  list_spring;              /**< The spring of a settle; it
                                              *   runs while the phase is
                                              *   SETTLE and no finger has
                                              *   caught it.                 */
    bool          list_low;                 /**< The finger left the first row down on the focus line: it lands there. */
    kui_drag_t    list_finger;              /**< The finger's samples: its
                                              *   speed at the release.       */

    /* THE SHELF OF RECENTS: the last apps that ran, a row of discs above the
     * root's first row (kgui_shelf.h, the launcher design of 5-nov, option
     * B). Its objects stand in the list's window beside the box, not in it,
     * so the rail's model is untouched; gui_list_place() puts them one pitch
     * above the first row, at the slide's x, and fades them before the
     * corners. The recents are kgui/recents, kept here as NVS holds them;
     * the shelf shows the ones still installed, at the root alone.
     *
     * shelf_sel is where the selection is: -1 on the rail, 0 to shelf_n - 1
     * on a recent. While it is on the shelf the rail stands at its first row,
     * unlit, and its ring is hidden: one ring at a time. */
    char          recents[KGUI_RECENTS_LEN];          /**< kgui/recents as it stands. */
    lv_obj_t     *shelf_disc[KGUI_SHELF_MAX];         /**< The discs, left to right. */
    lv_obj_t     *shelf_ring;                         /**< The focus ring on a recent, the kit's. */
    lv_obj_t     *shelf_label;                        /**< The focused recent's name, above the shelf. */
    char          shelf_name[KGUI_SHELF_MAX][KGUI_SHELF_NAME_MAX]; /**< Each disc's app, by project name. */
    uint8_t       shelf_idx[KGUI_SHELF_MAX];          /**< ...and its place in installed[] as the last refresh found it. */
    uint8_t       shelf_n;                            /**< How many discs show: 0 is no shelf. */
    int8_t        shelf_sel;                          /**< The recent the selection is on; -1 for the rail. */
    int8_t        lp_shelf;                           /**< The disc under the finger, for the long press; -1 for none. */
    int32_t       shelf_cy;                           /**< The discs' middle on the glass, as last placed. */
    uint8_t       shelf_opa;                          /**< How much of the shelf shows, as last placed. */
    uint8_t       shelf_pop[KGUI_SHELF_MAX];          /**< Each disc's coming in from the face, 0 to 255. */
    bool          shelf_ring_down;                    /**< The ring is on its way down to the first row: the rail's stays hidden till it lands. */
    int32_t       shelf_ring_fx;                      /**< Where the ring's glide began, from its target, across. */
    int32_t       shelf_ring_fy;                      /**< ...and down. */
    int32_t       shelf_ring_ox;                      /**< How far the ring stands from its target now, across. */
    int32_t       shelf_ring_oy;                      /**< ...and down. */
    int8_t        shelf_label_at;                     /**< The recent the name says, or is about to; -1 for none. */
    uint8_t       shelf_label_opa;                    /**< The name's own fade, 0 to 255. */
    int32_t       shelf_label_rise;                   /**< How far below its place the name stands as it comes in. */

    /* THE LONG PRESS: the launcher row or the control-centre circle a
     * finger landed on, and when. A press that stays on it for
     * GUI_LONG_PRESS_MS without a claim opens the row's details or the
     * radio's page (gui_long_press_tick()). */
    int8_t        lp_row;                   /**< The row under the finger; -1 for none. */
    uint8_t       lp_ctl;                   /**< The circle under the finger, Wi-Fi or Bluetooth; GUI_SET_COUNT for none. */
    uint32_t      lp_ms;                    /**< When the finger landed on it. */

    /* THE DETAILS' ROW, by what it is and what it is called: an index into
     * rows[] would be another app's after a rescan. */
    uint8_t       dt_kind;                  /**< Its GuiRowKind. */
    char          dt_name[KODE_APP_FILE_MAX]; /**< Its gui_row_name(): the project of an installed app, the file of a file. */

    /* REMOVE: the app being removed and how the wait for it stands. */
    char          rm_name[GUI_APP_NAME_MAX];       /**< Its project name: what the erase names. */
    char          rm_label[KODE_APP_DISPLAY_MAX];  /**< What the cards call it. */
    uint32_t      rm_since_ms;              /**< When the erase was asked. */
    uint32_t      rm_ask_ms;                /**< When the question was written: its pill takes no answer for GUI_REMOVE_GUARD_MS. */
    bool          rm_busy;                  /**< An answer is on its way (the question's, or the erase): a second one is ignored until the card ends. */
    uint32_t      rm_poll_ms;               /**< When the apps were last asked about. */

    /* THE FACTORY RESET: the request that is out, and AO_Boot's answer as
     * the wait card reads it. */
    bool          rs_busy;                  /**< AO_Boot was asked and has not answered: a second request is not sent. */
    bool          rs_answered;              /**< AO_Boot said the reset did not happen: the wait card says why. */
    uint8_t       rs_step;                  /**< The step that stopped it (FactoryResetRspEvt.step). */
    uint8_t       rs_status;                /**< ...and that step's kode_status_t. */

    /* THE PAD's hold-to-repeat, on up and down. pad_dir is the live press
     * (0 when none), pad_hold_ms when it landed, pad_step_ms when the last
     * row was stepped. The tick owns the repeat because the tick is the one
     * clock this AO has; a timer of its own would be a second one. */
    int8_t    pad_dir;
    uint32_t  pad_hold_ms;
    uint32_t  pad_step_ms;
    uint8_t   pad_repeats;   /**< Repeats since the press: what the hold's
                               *   quickening counts. */
    uint8_t   btn_held;  /**< One bit per button whose last edge was a
                           *   press (1 << kdrv_button_t): the buttons down
                           *   right now, kept from the edges on every screen
                           *   that hears them (gui_btn_track()). A button held
                           *   down is input for as long as it is down, and
                           *   nothing else says so - a held pad button stops
                           *   repeating at the end of the list, and a held
                           *   side button is disarmed by its own hold - so the
                           *   auto-lock reads this (gui_idle_check()). The
                           *   guided tests, which hear no edge of their own,
                           *   clear it as they take the glass.             */

    bool      writing;   /**< A write is in flight and the Opening sheet is
                           *   saying so. False the moment it ends, however
                           *   it ended, including while the failure sheet
                           *   still stands over it. Mirrored into
                           *   GuiStateEvt for `gui`; the state machine
                           *   itself is the truth. */
    bool      top_armed;    /**< The top button is down on the launcher and
                              *   its release will launch, if nothing
                              *   disarms it first. */
    uint32_t  top_press_ms; /**< When that press landed (khal_time_ms()).
                              *   Only meaningful while top_armed - the
                              *   release measures against it and refuses a
                              *   glitch or a hold. */
    bool      bot_armed;    /**< The bottom button is down and its release
                              *   will act - the lock, the settings screen
                              *   going back up, or closing a card - if it
                              *   comes before the hold. On the face the
                              *   release only says it is locked, and the
                              *   press arms so that the top button pressed
                              *   with it arms nothing. */
    uint32_t  bot_press_ms; /**< khal_time_ms() at the bottom press edge. */
    bool      bot_face;     /**< The bottom button is down and its press was
                              *   the awake face's. Unlike bot_armed it
                              *   survives the hold, which disarms every
                              *   press (Gui_running's BUTTON_HOLD_SIG): the
                              *   release that follows a hold is what sends
                              *   the Lock to Rest (gui_face_navigate()). */
    bool      bot_hold;     /**< The bottom button is down, and the face's red
                              *   arc counts the hold (gui_off_arc_counts()).
                              *   Set by its press on the face, the launcher,
                              *   the settings screen or a card over any of
                              *   them (gui_bot_track()); ended by its
                              *   release, by the arc when it is whole, and by
                              *   a state taking the glass: the face on its
                              *   entry, which spends a hold under way as it
                              *   came, and a guided test. Not an armed
                              *   press: a hold does not end it. */
    uint32_t  bot_hold_ms;  /**< khal_time_ms() at the press it counts from. */
    char      write_name[KODE_APP_FILE_MAX];
                         /**< What the Opening sheet is about, named the way
                           *   a person would: the display name the pill
                           *   carried, the file's stem, or "kodeOS". Written
                           *   when this launcher asks for an install and
                           *   again on every progress report, whoever
                           *   started the write, because APP_FLASH_FAIL_SIG
                           *   carries a reason and no name. Read only by
                           *   a sheet that is about no row of this list -
                           *   a console write, or an OS update - because a
                           *   row names itself. */
    bool      open_hold; /**< A run is out and the Opening card waits for it
                           *   to take the board away. False means nothing
                           *   is being waited for: no run is out, or a
                           *   write is reporting. The parent's tick watches
                           *   the deadline below, and its passing says the
                           *   app did not open. */
    uint32_t  open_hold_until; /**< khal_time_ms() at which that wait gives
                                 *   up: GUI_OPEN_RUN_MS after the run was
                                 *   asked for. */
    uint8_t   write_pct; /**< How far that write has got, 0..100. The value
                           *   row's fill IS this number, and a run request
                           *   shows it full: nothing is being written, the
                           *   board is already on its way out. */
    struct {
        bool run;                       /**< Installed app, or a file to
                                          *   install first. */
        char name[KODE_APP_FILE_MAX];   /**< The project name for a run, the
                                          *   file name for an install - what
                                          *   the request took. Empty means
                                          *   this launcher started nothing,
                                          *   and the failure sheet offers no
                                          *   Retry it cannot make good. */
    } last_launch;       /**< The request Retry repeats. Not the selection:
                           *   the list is rescanned while the sheet is up
                           *   and sel_idx may point somewhere else by the
                           *   time a failure is read. */
    bool      run_after; /**< The write on the glass is this launcher's own,
                           *   asked for without a launch (a file pill, or
                           *   Retry of one): its done runs the app it
                           *   installed, once the edge has closed. The one
                           *   thing that tells that done from a console
                           *   write's or the radio's, which run nothing from
                           *   here. */
    bool      closing;   /**< The edge is closing on the Opening card: the
                           *   write is done, and the run is asked for once
                           *   closing_until has passed. */
    bool      closing_run; /**< What follows the close: the run of the app
                             *   the launcher wrote; false for the card
                             *   leaving, as after every other write. */
    uint32_t  closing_until; /**< khal_time_ms() at which the close ends:
                               *   KGUI_EDGE_DONE_MS after it began. */
    GuiAsk    ask;           /**< The request held back for the Opening card:
                               *   AO_AppMgr is asked once the card has risen
                               *   (gui_write_ask()). */
    char      ask_name[KODE_APP_FILE_MAX]; /**< Its name: the project for a
                               *   run, the file for a write. */
    bool      ask_landed;    /**< The card is there: it has risen, or it is
                               *   shown at once. */
    uint32_t  ask_seen;      /**< `flushes` when it landed: a pass that moves
                               *   it has drawn the card. */
    uint32_t  ask_ms;        /**< khal_time_ms() when the request was held
                               *   back, then when the card landed: what the
                               *   limits count from. */

    /* The install of a file from the SD: asked about, then written
     * (GuiInstall says which). */
    GuiInstall inst_stage;   /**< Where the install of a file has got to.    */
    char      inst_file[KODE_APP_FILE_MAX];       /**< The file that is to be written. */
    char      inst_project[KODE_APP_PROJECT_MAX]; /**< Its project name; "" when not asked yet. */
    uint32_t  inst_size;     /**< The size the region would hold, in bytes.  */
    uint8_t   inst_tries;    /**< Busy answers asked again so far.           */
    uint32_t  inst_ask_ms;   /**< khal_time_ms() when the question last went out. */
    bool      inst_out;      /**< A question is out and AO_AppMgr's end of it has not come: none is asked until it does, or is lost (GUI_EVICT_LOST_MS). */
    bool      inst_retry;    /**< A busy answer is to be asked again.        */
    uint32_t  inst_again_ms; /**< khal_time_ms() at which that happens.      */
    bool      btn_dead;      /**< The press on the answer button began while its card refused input: its click answers nothing. */
    bool      bot_card_ok;   /**< The press of BOT now down began on a system card that took input: only such a press closes it by home. */
    kgui_ring_t glass;       /**< The edge along the glass: a write's progress, a wait, a done and a cut. */
    kgui_sys_t  sys;         /**< The frame of a system screen: protagonist, figure and words. */
    kgui_rise_t rise;        /**< How a system card arrives and refuses input. */
    kgui_return_t back;      /**< The wait of the first frame after an app. */
    kgui_welcome_t welcome;  /**< This boot lands from Welcome (kgui_welcome.h). */
    kboot_app_end_t back_end; /**< How the app before this boot ended. */
    char      stopped_name[KODE_APP_PROJECT_MAX]; /**< The app the stopped card is about, by project name. */
    kgui_crit_t crit;        /**< Whether the critical battery card has been raised for this entry. */
    bool      ran_checked;   /**< This boot looked for the app that ran before it (gui_last_follow_offset()). */

    /* The settings screen. sel follows the launcher's grammar one level
     * down: one control carries the cursor, and every question a control can
     * ask is asked on a sheet. */
    uint8_t  set_sel;               /**< GuiSetCtl: which control the ring is
                                      *   on. Outlives the screen, so coming
                                      *   back lands where you left. */
    /* The self-test. The report is AO_Autotest's; what is here is the copy
     * its events brought, which the Self-test page is written from. */
    uint8_t  test_rep_id[AUTOTEST_RUN_MAX];    /**< AUTOTEST_ID_*, a row each. */
    uint8_t  test_rep_state[AUTOTEST_RUN_MAX]; /**< How each ended.           */
    uint8_t  test_rep_n;            /**< Rows of the copy; 0: none kept.     */
    uint8_t  test_rep_fill;         /**< Rows gathered of the answer that is
                                      *   arriving.                          */
    uint8_t  test_rep_problems;     /**< Rows that failed or went unjudged. */
    uint32_t test_rep_when;         /**< UTC seconds of that run; 0: the
                                      *   clock was not set.                 */
    uint8_t  test_rows;             /**< The run in flight: how many rows.  */
    uint8_t  test_pos;              /**< Its row in flight, from 1.          */
    uint8_t  test_id;               /**< That row: AUTOTEST_ID_*.            */
    bool     test_held;             /**< It waits for TOP at its hold.       */
    bool     test_hands;            /**< It is past the hold: the rows that
                                      *   are answered on the pad.           */
    bool     test_stopping;         /**< A cancel was asked for.             */
    QStateHandler test_back;        /**< The screen state a guided test took
                                      *   the glass from, and gives it back to
                                      *   (gui_test_take(), gui_test_home()). */
    GuiSheet test_sheet;            /**< The sheet that was up over the settings
                                      *   screen when that test took the glass,
                                      *   or the details of an app over Apps;
                                      *   NONE when none was, or one that is not
                                      *   given back. */
    uint8_t  test_sel;              /**< The row the rail's ring stood on when
                                      *   that test took the glass.           */
    bool     test_sel_owed;         /**< The rail is to open on test_sel: its
                                      *   next shell entry takes it.         */
    QStateHandler screen;           /**< The screen state the glass is in:
                                      *   Gui_face, Gui_browsing, Gui_settings,
                                      *   Gui_btn_test or Gui_tp_test, from its
                                      *   entry to its exit; NULL in any other
                                      *   state. QHsm_isIn_() cannot say it in
                                      *   the middle of a step.              */
    kui_gesture_t gest;             /**< The live press, or the one just
                                      *   lifted, through the recognizer: it
                                      *   decides every door and every tap
                                      *   (gui_gesture_feed()). Its state
                                      *   when the lift arrives is what
                                      *   gui_click_is_tap() answers; what
                                      *   LVGL does on its own - a scroll -
                                      *   is compared in the log.            */
    GuiTouchZone gest_zone;         /**< Where that press landed, as the
                                      *   recognizer was told.               */
    int32_t  gest_land_x;           /**< Where the finger first came down: a
                                      *   press landed again keeps it
                                      *   (gui_gesture_reland()).            */
    int32_t  gest_land_y;           /**< And its row.                        */
    bool     gest_relanded;         /**< The press was landed again past the
                                      *   edge's first samples: it is no tap. */
    kode_gui_gesture_t gest_count;  /**< What the gestures have done since
                                      *   boot, as `gui_info` reports it; its
                                      *   drag is read from the curtain's
                                      *   page when it is reported
                                      *   (gui_drag_word()).                 */
    const char *door_why[GUI_DOOR_COUNT];
                                    /**< What asked for each door, as it was
                                      *   last posted (gui_door_post()) and
                                      *   read by the state that answers it:
                                      *   one per door, so a door queued
                                      *   behind another of a different kind
                                      *   cannot change the first one's line.
                                      *   Literals, so the pointer is the
                                      *   copy.                              */
    uint32_t list_moved_ms;         /**< khal_time_ms() when the launcher's
                                      *   list last moved, by a finger, a
                                      *   spring or a landing: a drag down on
                                      *   it is the lock pull only once it
                                      *   has been still KGUI_LIST_STILL_MS. */
    uint32_t set_tick_ms;           /**< When the settings screen last asked
                                      *   for the RSSI (khal_time_ms()).     */
    kui_drag_t curtain;             /**< The curtain's page, from 0 (the
                                      *   panel all above the glass) to the
                                      *   glass's height (all the way down).
                                      *   A door starts it and its spring
                                      *   lands it.                          */
    GuiCurtainKind curtain_kind;    /**< Which curtain the page moves.       */
    uint32_t curtain_slide_ms;      /**< A sideways curtain: when it started
                                      *   (khal_time_ms()).                  */
    int32_t  curtain_slide_off;     /**< A sideways curtain: where its panel
                                      *   stands, 0 to the glass's width; a
                                      *   clocked one, to its height.        */
    bool     curtain_clock;         /**< The settings curtain a button asked
                                      *   for runs on the clock, as kshell's
                                      *   window does (120 ms ease-out down,
                                      *   100 ms ease-in up), not on the
                                      *   finger's spring.                   */
    bool     door_mirrored;         /**< The launcher door posted last was a
                                      *   swipe right: the face leaves to the
                                      *   right as Apps comes in from the
                                      *   left. Spent by the door.           */
    uint8_t  home_way;              /**< A swipe's side for the way back to
                                      *   the face (GUI_HOME_FROM_LEFT or
                                      *   _RIGHT), or GUI_HOME_AS_CAME to
                                      *   mirror how the face left. Spent by
                                      *   the home door.                     */
    bool     curtain_mirrored;      /**< A sideways curtain runs the other
                                      *   way: the panel in from the right.  */
    GuiFrom  curtain_from;          /**< Settings only: the screen under the
                                      *   panel, which a closing curtain goes
                                      *   back to and an opening one came
                                      *   from.                              */
    bool     curtain_pull;          /**< The finger is the lock pull: its
                                      *   release is by position alone, and
                                      *   the face resists its first pixels
                                      *   (kgui_curtain_rubber()) until the
                                      *   page is caught.                    */
    bool     curtain_rubber;        /**< The extra resistance applies to the
                                      *   samples that follow.               */
    bool     curtain_up;            /**< A curtain is on the glass: its
                                      *   screen is loaded, and the screen
                                      *   the door started on is still the
                                      *   state. Put down by the landing or
                                      *   by leaving the state
                                      *   (gui_curtain_end()).               */
    bool     curtain_landed;        /**< It has landed and GUI_CURTAIN_LAND_SIG
                                      *   is on its way: the tick steps it
                                      *   no more.                           */
    bool     curtain_followed;      /**< A finger has followed this curtain:
                                      *   its landing is counted, a far one
                                      *   a commit and a near one a short.   */
    bool     curtain_opens;         /**< Which way: true brings the panel
                                      *   down, false takes it up again.     */
    bool     curtain_rescan;        /**< The landing on the launcher asks for
                                      *   a rescan (the bottom button's
                                      *   door; home does not).              */
    GuiFrom  settings_from;         /**< While the settings screen is the
                                      *   state: where it was opened from.   */
    const char *curtain_why;        /**< What asked for the door, for the
                                      *   lines it logs. A literal.          */
    uint32_t curtain_placed_ms;     /**< khal_time_ms() when the objects were
                                      *   last placed: the next placement
                                      *   waits KGUI_DRAG_PLACE_MS at least. */
    bool     curtain_arm;           /**< The finger has pulled the curtain
                                      *   past its commit point, and the tick
                                      *   for it was played: put down when it
                                      *   goes back.                         */
    lv_obj_t *fade_obj;             /**< The object drawn at half opacity for
                                      *   its one frame of fade, or NULL
                                      *   (gui_fade_start()).                */
    uint32_t fade_seen;             /**< `flushes` when it was set.          */
    uint32_t fade_ms;               /**< khal_time_ms() when it was set.     */
    bool     fade_hide;             /**< The fade ends by hiding the card
                                      *   it faded: a card going out.        */
    bool     sheet_cut;             /**< The sheet that is leaving goes at
                                      *   once, with no slide: the curtain is
                                      *   about to stand where it was, or a
                                      *   finger has already taken the card
                                      *   off the glass.                     */
    bool     sheet_instant;         /**< The sheet that is coming stands at
                                      *   its rest at once, with no slide:
                                      *   a curtain has just shown it.       */
    bool     card_arm;              /**< The finger has pulled the card past
                                      *   the point where letting go closes
                                      *   it, and the tick for it was
                                      *   played.                            */
    kui_drag_t card_drag;           /**< The card's page, from 0 (all the way
                                      *   down, off the glass) to the glass's
                                      *   height (up, where it rests): a
                                      *   finger on the card's header
                                      *   follows it (gui_card_touch()) and
                                      *   its spring lands it. At rest and
                                      *   open while no finger has taken a
                                      *   card.                              */
    bool     card_landed;           /**< It has landed and GUI_CARD_LAND_SIG
                                      *   is on its way: the tick steps it
                                      *   no more.                           */
    bool     card_followed;         /**< A finger has followed this card: its
                                      *   landing is counted, a down one a
                                      *   commit and an up one a short.      */
    uint32_t card_placed_ms;        /**< khal_time_ms() when the card was last
                                      *   placed: the next placement waits
                                      *   KGUI_DRAG_PLACE_MS at least.       */
    uint32_t idle_ms;               /**< khal_time_ms() of the last input on
                                      *   the launcher or the settings
                                      *   screen, or of the last moment the
                                      *   count was held (gui_idle_check()):
                                      *   what the auto-lock counts from.    */
    uint32_t lock_s;                /**< The auto-lock time in seconds, 0 for
                                      *   never: one of s_locks' times, read
                                      *   from kgui/lock at boot
                                      *   (gui_lock_load()) and changed by a
                                      *   pick from its list
                                      *   (gui_lock_pick()).                 */
    uint32_t sleep_s;               /**< `kody_sleep`: seconds on the awake
                                      *   face with no input before it rests,
                                      *   0 for never, GUI_SLEEP_LOCK to
                                      *   follow lock_s (gui_face_rest_s()). */
    bool     clock_12h;             /**< `clock=12h`: the face reads 1..12. */

    /* THE FACE. The date's label, which this AO writes - NULL when the
     * screen did not build it, and every use is guarded; the time's cells
     * are the screen's own to set (kgui_screen_face_time()) - and what is on
     * them: the minute shown, as gui_face_minute() numbers it, or 0 while
     * the time is unknown and the cells read --:--. face_painted false makes
     * the next pass paint whatever the minute is. */
    lv_obj_t *face_date;
    uint32_t  face_min;
    bool      face_painted;
    uint32_t  time_shown;           /**< The minute the Time page's two rows
                                      *   and the rail's Time row read, as
                                      *   gui_face_minute() numbers it, 0
                                      *   while the time is unknown
                                      *   (gui_time_fill(), gui_more_fill(),
                                      *   gui_time_follow()).                */
    uint8_t   off_mode;             /**< The red arc: GUI_OFF_IDLE, _FILL or
                                      *   _EMPTY (gui_off_arc_tick()).      */
    uint16_t  off_pm;               /**< The share of the arc drawn, in
                                      *   thousandths.                       */
    uint32_t  off_t0;               /**< When the arc began to empty.       */
    uint32_t  pile_key;             /**< What the face's battery was drawn
                                      *   from (gui_face_pile_paint()).      */
    bool      pile_drawn;           /**< The battery has been drawn once.   */
    bool      face_approx;          /**< The time painted was a restored one,
                                      *   put back after a power cut (the
                                      *   colon in Medium Grey).          */
    bool      face_react;           /**< Kody was asked to look; the face's
                                      *   tick answers it (gui_face_react()),
                                      *   never the input that saw it, and one
                                      *   not answered goes when the face
                                      *   stops being seen
                                      *   (gui_face_kody_hide()). The face
                                      *   asks for one when it comes back
                                      *   from Apps or Settings (Gui_face's
                                      *   entry).                          */
    char      zone[GUI_ZONE_MAX + 1U]; /**< The POSIX TZ string the clock
                                      *   runs in: AO_Boot keeps it, and this
                                      *   is its last answer (gui_zone_take());
                                      *   empty until the boot's read. */
    uint32_t  zone_asks;  /**< kgui's own `zone` requests, counted. */
    bool      zone_migrate; /**< kgui/zone was on the store at boot: the
                             *   boot's read decides its copy
                             *   (gui_zone_migrate()). */

    /* KODY ON THE FACE. One player for the whole boot, made in ui_build()
     * inside face_scene - NULL when it could not be, and then the face is
     * the time alone - and what the face's tick keeps about it: which scene
     * it plays and whether that scene is a choice, and whether it is on the
     * glass, which is all that decides whether he plays. */
    lv_obj_t    *face_kody;
    GuiSceneId   face_scene_on;     /**< The scene the face is on: the one
                                      *   the player plays, or the one just
                                      *   chosen, which Kody wakes in the
                                      *   next time he is seen.              */
    char         scene_stored[GUI_SCENE_NAME_MAX + 1U]; /**< What kgui/scene
                                      *   held at boot: a name the pack is
                                      *   not read yet to resolve, taken at
                                      *   KGUI_ASSETS_EV_RESOLVED; empty for
                                      *   none.                              */
    bool         face_rouse_owed;   /**< The scene's files were loading when
                                      *   Kody was to wake: KGUI_ASSETS_EV_SCENE
                                      *   wakes him.                         */
    bool         face_react_owed;   /**< A look was asked while its file was
                                      *   loading: KGUI_ASSETS_EV_REACTION
                                      *   plays it.                          */
    uint32_t     assets_t0_ms;      /**< khal_time_ms() the pack began to be
                                      *   read: the face's wait for it is
                                      *   counted from here.                 */
    bool         face_chosen;       /**< face_scene_on is a choice - a swipe
                                      *   sideways, the pad or the console
                                      *   made it, and kgui/scene keeps it -
                                      *   so the hour leaves it alone. false
                                      *   while none is chosen and the hour
                                      *   picks (gui_face_scene_want()).     */
    int8_t       face_hour;         /**< The local hour the face shows, or -1
                                      *   while the time is unknown: what the
                                      *   scene is picked by while none is
                                      *   chosen. Written with the minute
                                      *   (gui_face_time_paint()).           */
    GuiKodySight kody_sight;        /**< See GuiKodySight.                   */
    uint16_t     face_stood;        /**< The scene whose first frame stands in
                                      *   his box while the face has not been
                                      *   seen (gui_face_kody_ready()), or
                                      *   KUI_PACK_NONE.                      */
    bool         home_owed;         /**< The way home from Apps waits for him. */
    bool         home_pass;         /**< It has waited: the next one goes.    */
    uint32_t     home_owed_ms;      /**< Since when it waits.                 */
    bool         face_woke;         /**< Kody's wake-up has played in the
                                      *   scene the face is on: false from
                                      *   the boot, and from every change of
                                      *   scene - a choice, or the hour's -
                                      *   until it has
                                      *   (gui_face_scene_set(),
                                      *   gui_face_kody_rouse()).            */

    /* THE LOCK AT REST. The face has two substates: Gui_awake is the face as
     * the person uses it, and Gui_rest is the same face dimmed, with Kody
     * standing still (kgui_rest.h). These fields are what the two share. */
    bool         at_rest;           /**< Gui_rest is the state. Read where the
                                      *   state itself cannot be asked: the
                                      *   tick's wait, the scene and the
                                      *   pack, which leave Kody asleep.     */
    bool         woken;             /**< The Lock left Rest and nothing on the
                                      *   awake face has touched it since: it
                                      *   rests again after KGUI_WOKEN_REST_MS
                                      *   (gui_rest_after_ms()). The first
                                      *   input puts it down (gui_awake_input()).*/
    bool         usb_awake;         /**< A cable keeps the Lock awake: with
                                      *   VBUS present the time without input
                                      *   never takes it to Rest. The
                                      *   `usb_awake` setting.               */
    bool         rail_3v3;          /**< J3's +3.3V_EXT is on, as AO_Radio
                                      *   last said (EXP_POWER_SIG). Off until
                                      *   it says: kodeOS's link-up switches
                                      *   it off.                            */
    bool         rail_3v3_asked;    /**< A switch of it is asked and not
                                      *   answered yet.                      */
    bool         rail_5v;           /**< The PMIC's boost puts 5 V on J3, as
                                      *   AO_Power's last answer or reading
                                      *   says.                              */
    bool         rail_5v_asked;     /**< A switch of it is asked and not
                                      *   answered yet (POWER_CTRL_SIG).     */
    uint8_t      wake_btn;          /**< The button whose press woke the Lock,
                                      *   until its release: that press does
                                      *   nothing else, nor its hold, nor its
                                      *   release. GUI_WAKE_BTN_NONE
                                      *   otherwise.                         */
    bool         wake_touch;        /**< A finger came down at Rest and is
                                      *   still down: nothing of that touch
                                      *   reaches LVGL or the recognizer, even
                                      *   once the Lock has woken.           */
    bool         rest_knock;        /**< The top button was pressed once
                                      *   at Rest: "Press ● again" stands in
                                      *   the date's place and Kody alone is
                                      *   awake, in colour (gui_rest_knock()). */
    uint32_t     knock_ms;          /**< When rest_knock last changed: it
                                      *   ends KGUI_PEEK_MS later.           */
    bool         knock_pending;     /**< The board woke with a button: the
                                      *   face is entered at Rest with that
                                      *   press the knock (TOP) or the hint. */
    uint8_t      rest_fall;         /**< Where the fall into Rest stands
                                      *   (GUI_FALL_*). */
    uint32_t     rest_fall_ms;      /**< When <scene>_duerme began, at Rest. */
    lv_obj_t    *veil;              /**< Kody's last frame, fading out over
                                      *   the next one (gui_veil_show()). */
    uint8_t     *veil_px;           /**< That frame, in PSRAM. */
    lv_image_dsc_t veil_dsc;        /**< The picture it is shown by. */
    uint32_t     veil_ms;           /**< When the fade began. */
    uint32_t     woke_ms;           /**< When Rest last ended. */
    bool         woke_seen;         /**< It has, since the boot. */
    uint32_t     look_ms;           /**< When Kody last looked at you: once a minute. */
    bool         looked;            /**< He has, since the boot. */
    bool         joke_ok;           /**< Waking or back on the face: the joke may come. */
    uint32_t     joke_ms;           /**< When the last joke was asked. */
    uint32_t     joke_gap;          /**< How long until the next, 2 to 3 minutes; 0 not drawn. */
    int8_t       hour_was;          /**< The hour last seen; -1 unknown, -2 not looked at yet. */
    bool         hour_due;          /**< He owes a look at the time. */
    bool         power_seen;        /**< The cable has been read once: an edge means something. */
    uint8_t      chg_state;         /**< What the cable is doing (kgui_charge_t). */
    bool         plug_owed;         /**< The cable's notice waits for a reading that knows. */
    uint8_t      visit_kind;        /**< A notice that waits for the face (GuiVisit). */
    char         visit[48];         /**< Its text. */
    uint8_t      pill_wait;         /**< A notice waits for its reaction to begin (GuiVisit). */
    bool         pill_due;          /**< The notice comes at pill_on_ms. */
    bool         pill_up;           /**< The notice goes at pill_off_ms. */
    uint32_t     pill_on_ms;        /**< When it comes. */
    uint32_t     pill_off_ms;       /**< When it goes. */
    char         pill_text[48];     /**< What it says. */
    bool         sleep_cue;         /**< The bottom button has been held
                                      *   KGUI_SLEEP_CUE_MS on the face and
                                      *   <scene>_duerme plays
                                      *   (gui_sleep_cue_tick()). */
    bool         sleep_cue_rest;    /**< The release that sends the Lock to
                                      *   Rest came while the cue ran: Rest
                                      *   lets <scene>_duerme finish. */
    uint32_t     sleep_cue_rest_ms; /**< When that release came. */
    bool         date_seen_boot;    /**< The date has had its first showing since the boot. */
    uint32_t     date_until_ms;     /**< When the date under the hour goes; 0 when it is not shown. */
    bool         rest_drawn;        /**< A frame of Kody's scene is on the
                                      *   glass at Rest: frame 0 of its loop,
                                      *   or the one he was on when the scene
                                      *   could not be drawn (gui_rest_kody()). */
    bool         rest_painted;      /**< This Rest has read the minute
                                      *   rest_key (gui_rest_paint()).       */
    uint32_t     rest_key;          /**< That minute: gui_face_minute()'s
                                      *   number, or while the time is not
                                      *   known the board's own minutes.     */
    uint32_t     rest_step;         /**< Where the face's content stands in
                                      *   its cycle of offsets
                                      *   (kgui_rest_offset()), moved on at
                                      *   every minute of a Rest and kept
                                      *   from one Rest to the next.         */
    bool         rest_dimmed;       /**< The glass is below the stored
                                      *   brightness or on its way up or down:
                                      *   what AO_Display announces of the
                                      *   level is the step it was asked for,
                                      *   unless somebody stored another, so
                                      *   it is judged before it is taken
                                      *   (gui_settle_learn()).              */
    uint8_t      rest_stored;       /**< The stored brightness, in percent, as
                                      *   AO_Display last said it: the level
                                      *   every step is a share of and waking
                                      *   returns to.                        */
    bool         settle_ask;        /**< The stored level was asked of
                                      *   AO_Display, and its answer starts
                                      *   the steps (gui_settle_learn()).    */
    bool         settle_on;         /**< A brightness step is due at
                                      *   settle_ms.                         */
    bool         settle_dim;        /**< ...and the steps go down, otherwise
                                      *   up.                                */
    uint8_t      settle_i;          /**< ...the step due: an index into
                                      *   s_rest_steps.                      */
    uint8_t      settle_at;         /**< The step last asked of AO_Display.   */
    uint32_t     settle_ms;         /**< khal_time_ms() when the next step is
                                      *   due.                               */

    /* THE PASSES, MEASURED, for the debug log (log_level tag="kgui"
     * level=d). Every chunk handed to the panel moves `flushes`, so a pass
     * drew when it moved; while Kody plays on the face the passes that drew
     * add up into windows of GUI_FACE_WINDOW_MS, and a press waits for the
     * first pass after it that drew. */
    uint32_t     flushes;
    /* THE FRAMEBUFFERS. With two, LVGL draws straight into the panel's own
     * (direct mode), and a frame is handed over once, as the rows it changed
     * - see gui_flush_cb(). */
    bool         direct;            /**< LVGL draws in the panel's
                                      *   framebuffers.                      */
    bool         posted;            /**< A flush is with AO_Display and not
                                      *   yet waited for.                    */
    int32_t      band_y1;           /**< First and last row the frame being
                                      *   drawn has changed so far, in direct
                                      *   mode; empty when y1 > y2.          */
    int32_t      band_y2;
    uint32_t     face_window_ms;    /**< khal_time_ms() the window of Kody's
                                      *   play being counted opened at
                                      *   (gui_face_window_open()).          */
    uint32_t     pass_n;            /**< Passes that drew, this window.      */
    uint64_t     pass_sum_us;       /**< Their time, added up.               */
    uint32_t     pass_max_us;       /**< The longest of them.                */
    uint32_t     press_us;          /**< When the press being timed was
                                      *   dispatched (gui_now_us()).         */
    bool         press_timing;      /**< A press waits for its frame.        */
    bool         first_frame_seen;  /**< The boot's first frame has gone out
                                      *   and been logged.                   */
    bool         list_end_seen;     /**< The boot's installed list has ended
                                      *   and been logged.                   */

    /* THE SHEET: kodeOS's one popup, built once onto lv_layer_top() - above
     * every screen, so none of the screen state above has anything to say
     * about it. It is up or it is not, and while it is, it owns the input.
     *
     * ONE CARD, EVERY POPUP: a sheet raises it with rows or with lines, and
     * `sheet` says which kind - the pairing included, which is what stopped
     * it being a flag the whole state machine had to ask about. The two
     * fields it still owns below are the pairing's own state and not the
     * card's: what the code is, and whether it can still be refused. */
    lv_obj_t *sheet_root;    /**< The full-glass blocker. NULL: not built.  */
    lv_obj_t *sheet_card;    /**< The card that slides; its y is animated.  */
    lv_obj_t *sheet_body;    /**< Its column of rows.                       */
    int32_t   sheet_rest_y;  /**< Where kui_sheet.c put the card, read once:
                               *   the top of the glass, since a card is as
                               *   tall as the glass.                       */
    bool      page_grow;     /**< A page grows out of the glass's middle or
                               *   goes back into it, on the curtain's
                               *   pictures (gui_page_grow_start()).       */
    bool      page_grow_in;  /**< It grows in: the offset runs from the
                               *   glass's width to 0.                      */
    bool      page_grow_fades;  /**< It stands on no circle: it fades over the
                                  *   whole glass, in GUI_PAGE_ANIM_MS.      */
    bool      page_grow_shut;   /**< The sheet leaves the glass when it ends. */
    bool      page_grow_landed; /**< Its last frame is placed: the next tick
                                  *   ends it, once a pass has drawn it.   */
    uint32_t  page_grow_ms;  /**< khal_time_ms() when it began.             */
    uint32_t  page_grow_placed_ms; /**< When its pictures were last placed. */
    lv_obj_t *page_grow_back;  /**< The screen the glass shows when it ends. */
    lv_obj_t *page_grow_scr;   /**< The curtain's screen while it runs: any
                                 *   other loaded meanwhile ends it.        */
    lv_obj_t *page_veil;       /**< The black that covers the screen under a
                                 *   settings page at rest (gui_page_veil_tick()),
                                 *   or NULL.                               */
    int32_t   sheet_line1_y; /**< Where kui_sheet.c put line1, in the card.  */
    int32_t   hdr_title_y;   /**< Where kui_sheet.c put the title, in the
                               *   card.                                    */
    int32_t   hdr_foot_y;    /**< Where kui_sheet.c's header ends in the
                               *   card: the foot of the title disc, which
                               *   is where a card's header drag stops being
                               *   the header's.                            */
    GuiSheet  sheet;         /**< Which sheet is up; NONE when none.        */
    lv_obj_t *sheet_rows[GUI_SHEET_ROWS_MAX];
    uint16_t  sheet_tag[GUI_SHEET_ROWS_MAX];
                             /**< One number per row, and what it means is
                               *   the filler's to decide - a network's
                               *   index, a level, a verb. The row IS the
                               *   list here, so the thing a row is about
                               *   travels beside it rather than in a second
                               *   array the fillers would have to keep in
                               *   step.                                    */
    uint8_t   sheet_n;       /**< Rows in body.                             */
    uint8_t   sheet_sel;     /**< The ring's row.                           */
    uint32_t  sheet_value_ms; /**< When a finger dragging a value row last
                               *   moved the level, khal_time_ms(). The
                               *   throttle GUI_LEVEL_DRAG_MS measures, and
                               *   meaningless while no value row is under a
                               *   finger.                                  */
    bool      sheet_value_dirty; /**< A level is on the glass that its store
                               *   has not been told about: a finger is
                               *   dragging it and has not let go. Persisting
                               *   per sample would be twenty NVS writes a
                               *   second behind a number nobody has settled
                               *   on, so the write waits - and this is what
                               *   guarantees it still happens, on the
                               *   release, on the next pad press, or on the
                               *   card's own exit, whichever comes first. */
    bool      sheet_locked;  /**< The sheet is not navigable: no button, no
                               *   tap. What a sheet says while the
                               *   board is doing something it cannot be
                               *   talked out of.                           */
    bool      sheet_placed;  /**< The body's next scroll end is ours - the
                               *   landing's own travel, or the ring being
                               *   brought into view - and so is not a
                               *   finger's to land (on_sheet_scroll_end()).*/
    bool      sheet_owed;    /**< A rebuild the card is owed: something the
                               *   sheet is a view of moved while a finger
                               *   was on the glass. A card rebuilt under a
                               *   finger deletes the very row LVGL is
                               *   scrolling, which is how a Wi-Fi page
                               *   answering its scan ate the drag on it.   */
    int8_t    sheet_row;     /**< Which launcher row the sheet is ABOUT, or
                               *   -1 for none. The details are the row they
                               *   was opened on and the Opening sheet the
                               *   row that was launched, and a row is an
                               *   index into rows[] - so the fill checks it
                               *   against row_count before reading, because
                               *   a list that moved under an open sheet is a
                               *   list this number no longer points into.  */
#if CONFIG_KODEOS_BLE_PAIRING_PASSKEY
    bool      pair_live;     /**< A pairing is in flight: a code is up and
                               *   the bottom button can still refuse it.   */
    bool      pair_hold;     /**< The outcome is on the glass, with nothing
                               *   left to refuse, until pair_until.        */
    uint32_t  pair_until;    /**< When it goes (khal_time_ms()).            */
    char      pair_code[8];  /**< The passkey as it is read out: six digits,
                               *   zero-padded. Kept rather than written
                               *   straight onto the glass, because the
                               *   sheet is rebuilt from this AO's fields
                               *   every time it is refilled.               */
    const char *pair_why;    /**< What the outcome was, or NULL while the
                               *   code is still up. A literal, so the
                               *   pointer is the copy.                     */
#endif

    /* The control centre's controls, index-aligned with GuiSetCtl - so set_sel is an
     * index into this array and into nothing else. */
    lv_obj_t *set_ctl[GUI_SET_COUNT];

    /* What the four subscriptions last said. The grid is a view of these and
     * of nothing else: gui_cc_paint() repaints the circles from them every
     * time one of the four events arrives. Kept as a copy, per rule 7 -
     * these arrive as events and the events are gone by the next tick. */
    bool     wifi_on;        /**< The service flag as the person set it, not the association. */
    bool     wifi_real;      /**< The service flag as the radio last said it. */
    uint8_t  wifi_wish;      /**< A switch not answered yet (GUI_WISH_*). */
    uint32_t wifi_wish_ms;   /**< When it was pressed. */
    bool     ble_real;       /**< The stack as the radio last said it. */
    uint8_t  ble_wish;       /**< A switch not answered yet (GUI_WISH_*). */
    uint32_t ble_wish_ms;    /**< When it was pressed. */
    bool     wifi_linked;    /**< Associated with an address.               */
    int8_t   wifi_rssi;      /**< dBm of that association.                  */
    char     wifi_ssid[GUI_SSID_BYTES]; /**< 32 plus the terminator (802.11).   */
    bool     wifi_reconnecting; /**< Off its network and getting back on one. */
    bool     radio_relinking; /**< The link to the radio chip was lost and is
                               *   being built again.                       */
    bool     radio_gave_up;  /**< ...and nothing more is tried until somebody
                               *   asks: Wi-Fi and Bluetooth do nothing.    */
#if CONFIG_KODEOS_CHANNEL
    uint8_t  chan_state;     /**< chan_state_t: where the Kode channel is.  */
    uint32_t chan_at_ms;     /**< khal_time_ms() when CHANNEL_STATE_SIG last
                               *   came: the wait is counted from here.      */
    uint32_t chan_wait_ms;   /**< CHAN_WAITING: the wait it announced then.  */
    uint32_t chan_shown_s;   /**< The seconds the row's line says now, so the
                               *   tick rewrites it when they change only.   */
    char     chan_why[24];   /**< The reason it gave, "" when none.         */
    bool     chan_nowhere;   /**< Its last wait said the network reaches
                               *   nothing (kgui_wifi_goes_nowhere()); kept
                               *   through the next try, until it is up or
                               *   the network changes.                     */
#endif
    bool     ble_on;         /**< The stack is up, whatever it is doing.    */
    bool     adv_on;         /**< The board is on the air and can be found:
                               *   advertising, and not hidden.            */
    bool     ble_pair_open;  /**< Pair new device's time is running.        */
    bool     ble_console;    /**< A central is attached to the console.     */
    uint8_t  ble_bonds;      /**< Bonded peers in the store. A COUNT is all
                               *   the radio exposes - no names, no
                               *   addresses - and the sheet says exactly
                               *   that rather than inventing a list.      */
    uint32_t ble_blink_ms;   /**< When the advertising blink last changed
                               *   half (khal_time_ms()).                  */
    bool     ble_dim;        /**< Which half that is: the circle's glyph is
                               *   currently drawn faded. Kept so leaving
                               *   the screen can put it back at full
                               *   opacity rather than leaving it half-lit. */
    uint8_t  bright;         /**< What the panel is driven at, in percent:
                               *   the Screen sheet's bar. Only
                               *   DisplayStateEvt knows it.                */
    uint8_t  vol;            /**< The speaker's level, in percent: the control
                               *   centre's volume bar. Only AO_Audio knows
                               *   it, and it tells this AO when asked. */
    bool     vol_dirty;      /**< A volume is on the speaker that its store has
                               *   not been told about: a finger is dragging
                               *   it, or the pad moved it and the request
                               *   was refused. The release, the next pad
                               *   press or the screen's exit keeps it. */
    uint8_t  soc;            /**< Charge left, in percent: the Battery
                               *   sheet's bar.                             */
    uint8_t  bat_state;      /**< What that much means: GUI_SET_BAT_*.      */
    lv_obj_t *deep_warn;     /**< The count before the deep rest, over everything. */
    lv_obj_t *deep_digit;    /**< Its figure. */
    lv_obj_t *deep_words;    /**< Its words. */
    bool     deep_fading;    /**< They are going: the glass ends black. */
    uint32_t deep_ms;        /**< When Rest last saw anybody. */
    uint32_t deep_ends_ms;   /**< When the count ends. */
    uint32_t deep_asked_ms;  /**< When the rest was asked for. */
    bool     deep_asked;     /**< It has been asked for, and the answer waits. */
    bool     deep_forced;    /**< `deep_warn` asked: a cable does not stop it. */
    bool     write_cancel;   /**< The person went back from a write: its end says nothing. */
    uint32_t write_cancel_ms; /**< When. */
    bool     assets_owed;    /**< The pack resolved before the face existed. */
    bool     zone_heard;     /**< AO_Boot has said what zone is on, and whether chosen. */
    bool     zone_stored;    /**< Somebody chose the zone. */
    bool     prompt_open;    /**< A pill on the face asks for a page: it may rise over it. */
    int32_t  page_scroll[3]; /**< Where each page stood when a deeper one opened. */
    uint8_t  page_scroll_n;  /**< How many are kept. */
    kgui_haptic_level_t haptic_pref; /**< What the Vibration row chose; the volume's stops may ask otherwise. */
    char     ble_name[GUI_BLE_NAME_MAX + 1U]; /**< The name chosen for Bluetooth; empty for the serial. */
    bool     first_hold;     /**< The glass stays black: the first thing lit is whole. */
    uint32_t first_hold_ms;  /**< Since when. */
    bool     rest_hint;      /**< Rest says how to wake: any input but the top button. */
    uint32_t rest_hint_ms;   /**< When it started saying so. */
    bool     knock_hint;     /**< The board woke by BOT: Rest says how, no knock. */
    bool     lp_woke_top;    /**< The board woke from its low-power rest by TOP. */
    uint8_t  lp_wake_id;     /**< The button whose press and release that wake swallows. */
    bool     level_grow;     /**< A folder's way in or out is fading, on the curtain's pictures. */
    uint32_t level_grow_ms;  /**< When it began. */
    uint32_t level_grow_placed_ms; /**< When it was last placed. */
    lv_obj_t *level_title;   /**< Apps: the folder's title and the arrow back. */
    lv_obj_t *page_title;    /**< A settings page: its title and the arrow back. */
    bool     radio_from_more; /**< The Wi-Fi or Bluetooth page was opened from Settings' list. */
    bool     about_tech;     /**< About shows its technical rows. */
    bool     bat_from_cc;    /**< The Battery page was opened from the
                               *   control centre's circle: it stands alone
                               *   there, and closing it goes back to the
                               *   circles, not to Settings.               */
    bool     bat_done;       /**< The charger reached termination
                               *   (KDRV_BQ_CHRG_DONE). Not a grade - a full
                               *   cell on the cable is not charging and is
                               *   not discharging either, and the Battery
                               *   sheet is where that third word goes.     */
    bool     vbus;           /**< The cable is in: the Battery sheet's "On
                               *   USB" and the Power off sheet's USB note. */
    /* The rest of the same reading, kept for the Battery sheet alone: the
     * battery's grade is a colour and these three are the numbers behind the
     * charge. Copies, per rule 7. */
    uint16_t vbat_mv;        /**< The cell's terminal voltage.              */
    int16_t  current_ma;     /**< Into the cell positive, out negative.     */
    int8_t   temp_c;         /**< The gauge's TS pin, whole degrees.        */
    bool     temp_known;     /**< A POWER_FIELD_SIG carrying it answered.   */
    /* What the About sheet is a view of, and none of it changes while that
     * sheet is up except the uptime, which the sheet reads for itself. */
    uint32_t c5_fw[3];       /**< The C5's major, minor and patch.          */
    bool     c5_fw_known;    /**< The link answered the version RPC.        */
    bool     sd_mounted;     /**< A card is mounted (STORAGE_INFO_SIG).     */
    bool     settings_owed;  /**< gui_settings_ask() waits for kode_up().   */
    bool     ble_name_owed;  /**< The stored Bluetooth name waits for kode_up(). */
    /* The kept copy of the lists (gui_keep_*()). */
    uint8_t  keep_read;      /**< Where the read of the card's copy stands (GUI_KEEP_READ_*). */
    uint32_t keep_off;       /**< The read's or the write's next byte. */
    uint32_t keep_total;     /**< What the block holds, for the write. */
    uint32_t keep_refused;   /**< The CRC of the copy the card last refused, not offered again. */
    QTimeEvt keep_retry;     /**< A refused read goes out again. */
    uint32_t keep_verify_ms; /**< When the copy is checked against the card; 0 for never. */
    uint32_t keep_save_ms;   /**< When a folder last changed something. */
    bool     keep_ok;        /**< The block holds a whole copy, not yet taken in. */
    bool     keep_seeded;    /**< The lists came from the copy and are unchecked. */
    bool     keep_dirty;     /**< A folder has answered since the last save. */
    bool     keep_writing;   /**< The card's copy is being written. */
    bool     keep_gate_open; /**< The link may speak: radio_boot_release() went. */
    bool     keep_listed;    /**< The card's first listing has ended. */
    bool     keep_pack_owed; /**< Kody's pack waits for the read of the card's copy. */
    bool     sd_known;       /**< AO_Storage has answered at least once.    */
    uint32_t sd_card_mb;     /**< How big the CARD is, as it identified
                               *   itself; 0 when it did not say. Not the
                               *   volume's size - a card is not obliged to
                               *   carry a filesystem that spans it.        */
    uint8_t  write_what;     /**< kwrite_t: what the write on the glass is
                               *   and how it ends - the Opening sheet's
                               *   title, name and sentence, and the
                               *   failure's, all follow from it.          */
    uint8_t  fail_why;       /**< kfail_t of the failure on the glass: what the
                               *   failure card says, beside write_what's title. */
#if CONFIG_KODEOS_WIFI
    /* The two lists the Wi-Fi sheet is a view of: what is in the room and
     * what this board remembers. Copies, per rule 7 - they arrive one event
     * per entry and the events are gone by the next tick - and both carry
     * a "foreign round" guard, because `wifi_scan` from the console publishes
     * the same conversation the sheet asks for.
     */
    char     scan_ssid[KDRV_WIFI_SCAN_MAX][GUI_SSID_BYTES];
    int8_t   scan_rssi[KDRV_WIFI_SCAN_MAX];
    uint8_t  scan_auth[KDRV_WIFI_SCAN_MAX];  /**< 0 is an open network.     */
    bool     scan_seen[KDRV_WIFI_SCAN_MAX];  /**< Heard in the round under way. */
    uint8_t  scan_miss[KDRV_WIFI_SCAN_MAX];  /**< Answered rounds in a row that did not hear it. */
    bool     scan_dirty;     /**< Heard something the rows do not show yet. */
    uint32_t scan_paint_ms;  /**< When the rows were last written from it. */
    char     scan_shown[KDRV_WIFI_SCAN_MAX][GUI_SSID_BYTES];       /**< What the rows say, whatever the round has moved since. */
    uint8_t  scan_shown_auth[KDRV_WIFI_SCAN_MAX];
    uint8_t  scan_shown_n;
    uint8_t  scan_n;
    bool     scan_out;       /**< A scan this AO asked for has not answered
                               *   yet. One question at a time: the radio
                               *   refuses a second, and its refusal is an
                               *   empty listing that blanks the page.      */
    uint32_t scan_out_ms;    /**< When the scan out was asked: one never answered is given up after GUI_WIFI_SCAN_LOST_MS. */
    bool     scan_refused;   /**< The last sweep was refused: the radio's next
                               *   WIFI_STATE_SIG asks again.               */
    bool     scan_fresh;
    bool     scan_answered;  /**< A round has reached its end since the radio
                               *   came on: only then can "No networks found"
                               *   be true. A refusal never sets it.         */
    uint32_t scan_end_ms;    /**< When that round ended.                     */
    char     saved_ssid[GUI_WIFI_SAVED_MAX][GUI_SSID_BYTES];
    uint8_t  saved_n;
    bool     saved_fresh;

    /* THE KEYPAD'S ERRAND (GUI_SHEET_KEYPAD). What it is for is here; what is
     * typed is NOT: that lives in kgui_keyboard.c alone, and is never in this
     * struct, in an event of this AO's, in the log or in `gui_info`. */
    uint8_t  kbd_stage;      /**< GUI_KBD_* stage.                         */
    char     kbd_ssid[KUI_MULTITAP_SSID_MAX + 1U];
                             /**< The network the keypad is for: a copy, because
                              *   the scan above is rewritten while it is up; for
                              *   a hidden network, the name once it is typed. */
    bool     kbd_secured;    /**< The network has a password, so Join with
                              *   nothing typed is no join.                 */
    uint16_t kbd_door;       /**< The tag of the Wi-Fi row that opened the keypad,
                              *   where the ring goes back to.              */
    uint8_t  kbd_join_dot;   /**< How many dots after Joining, less one. */
    uint32_t kbd_join_ms;    /**< khal_time_ms() when the join was asked for. */
    bool     kbd_secret;     /**< The keypad is up and holds the pad's lines back
                              *   from the log (gui_secret_begin()).         */
#endif
    bool     sheet_ask;      /**< Ask on the next tick, which is how opening
                               *   a sheet gets its first answer: the entry
                               *   only has to set it. Outside the Wi-Fi
                               *   guard because three sheets poll now - the
                               *   networks, the battery and the uptime.    */
    uint32_t sheet_ask_ms;   /**< When the sheet last asked its owner for
                               *   something (khal_time_ms()).              */
#if CONFIG_KODE_LOWPOWER
    /* THE LOW-POWER ROUNDS (gui_lp_park(), gui_lp_resume(), and Rest's own,
     * gui_rest_park(), gui_rest_unpark()). Parked, this AO draws nothing and
     * runs no tick: the glass holds the black page, or the Rest face with
     * AO_Display writing the minute into the panel's memory from the strip. */
    uint8_t  lp_who;         /**< The id lowpower_join() gave; KODE_LOWPOWER_WHO_NONE
                               *   when the table was full and this AO sits out. */
    uint32_t lp_round;       /**< The round the park answers.                */
    uint8_t  lp_target;      /**< That round's kode_lp_state_t.              */
    bool     lp_parked;      /**< The glass was handed over: no tick, no
                               *   drawing, until gui_lp_resume().           */
    kgui_face_strip_t lp_strip; /**< The figures AO_Display writes the minute
                               *   from; freed once the board is awake.      */
    bool     lp_bot_down;    /**< BOT went down while parked and has not come up. */
    bool     lp_bot_cycle;   /**< A whole press of BOT went by while parked. */
    bool     lp_woke_bot;    /**< The board woke from its low-power rest by BOT, with or
                               *   without the press still down: Rest's first press. */
    bool     lp_bot_wake;    /**< BOT woke the board: its press and release
                               *   belong to the wake and do nothing else.   */
    bool     lp_bot_seen;    /**< The press of that wake has been seen.       */
    char     lp_refused[KODE_LOWPOWER_REFUSAL_MAX]; /**< Why the last request
                               *   this AO made was refused: "who: why".    */
    bool     lp_refused_due; /**< That refusal arrived while parked and is
                               *   still to be said on the glass.            */
    bool     lp_rest;        /**< The park is Rest's (Gui_rest_asleep): the
                               *   Rest face stays on the glass.            */
    bool     lp_top_down;    /**< TOP went down while parked and has not come up. */
    bool     lp_top_cycle;   /**< A whole press of TOP went by while parked. */
    bool     lp_park_top;    /**< TOP was pressed while Rest was parked: the
                               *   wake is the knock.                        */
    uint8_t  lp_woke_prev;   /**< The state the last STATE(AWAKE) left: AWAKE
                               *   for a round that was given up.            */
    bool     rest_calm;      /**< Rest has been settled since rest_calm_ms.  */
    uint32_t rest_calm_ms;   /**< Since when.                                */
    bool     rest_asked;     /**< Rest asked for ASLEEP and has not slept since. */
    uint32_t rest_asked_ms;  /**< When.                                      */
    bool     rest_held;      /**< That ask ended awake: rounds for ASLEEP are
                               *   refused at Rest until Rest asks again.    */
    uint32_t rest_parks;     /**< Rests that slept: each sleeps at the next
                               *   place of the burn-in cycle.               */
#endif
#if CONFIG_KODE_TEST_DOT
    kgui_td_req_t td_first;  /**< The request that took the glass for the E5
                               *   test, shown by Gui_test_dot's entry.      */
#endif
} Gui;

